function TeacherDashboard({ data, setSection }: { data: any; setSection: (s: Section) => void }) {
  const pendingGrades = data.submissions.filter((s: any) => s.grade === null).length;
  return <div className="editorial-dashboard teacher-dashboard"><PageHeader eyebrow="Tu espacio docente" title={roleGreetings.teacher} detail="Aquí tienes lo esencial para que tu jornada avance sin fricción." action={<Button onClick={() => setSection("classroom")} className="rounded-xl bg-[var(--edc-primary)]"><Plus className="mr-2 h-4 w-4" />Crear tarea</Button>} /><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Por calificar" value={pendingGrades || 2} detail="Entregas pendientes" icon={ClipboardList} accent="amber" /><StatCard label="Mis cursos" value={2} detail="11-1 y 11-2" icon={BookOpen} accent="blue" /><StatCard label="Asistencia" value="1" detail="Registro pendiente" icon={ClipboardCheck} accent="green" /></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><Card className="border-0 shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl"><CardHeader><div className="flex items-center justify-between"><div><CardTitle className="text-base">Próximas clases</CardTitle><p className="mt-1 text-xs text-slate-400">Tu agenda para hoy.</p></div><button onClick={() => setSection("calendar")} className="text-xs font-semibold text-[var(--edc-primary)]">Ver calendario</button></div></CardHeader><CardContent className="space-y-3">{[["7:00 a. m.", "Matemáticas", "11-2", "Aula 204"], ["9:00 a. m.", "Física", "11-1", "Laboratorio"], ["11:00 a. m.", "Matemáticas", "11-1", "Aula 107"]].map(item => <div key={item[0] + item[2]} className="flex items-center gap-4 rounded-xl border border-slate-100 p-3"><div className="w-16 text-xs font-semibold text-[var(--edc-primary)]">{item[0]}</div><div className="h-8 w-px bg-slate-200" /><div className="flex-1"><p className="text-sm font-semibold text-slate-700">{item[1]}</p><p className="mt-0.5 text-xs text-slate-400">{item[2]} · {item[3]}</p></div><ChevronRight className="h-4 w-4 text-slate-300" /></div>)}</CardContent></Card><Card className="border-0 bg-[var(--edc-secondary)] shadow-none rounded-2xl"><CardContent className="p-6"><div className="flex items-center gap-2 text-[var(--edc-primary)]"><ClipboardList className="h-5 w-5" /><span className="text-xs font-semibold uppercase tracking-[0.14em]">Pendientes</span></div><div className="mt-6 space-y-4"><div className="flex items-end justify-between"><p className="text-sm text-slate-600">Entregas por calificar</p><p className="text-2xl font-semibold text-slate-900">{pendingGrades || 2}</p></div><div className="h-1.5 rounded-full bg-white"><div className="h-1.5 w-2/3 rounded-full bg-[#368de8]" /></div><div className="flex items-end justify-between"><p className="text-sm text-slate-600">Asistencia pendiente</p><p className="text-2xl font-semibold text-slate-900">1</p></div><div className="h-1.5 rounded-full bg-white"><div className="h-1.5 w-1/3 rounded-full bg-[#77b6f1]" /></div><div className="flex items-end justify-between"><p className="text-sm text-slate-600">Actividad por publicar</p><p className="text-2xl font-semibold text-slate-900">1</p></div><div className="h-1.5 rounded-full bg-white"><div className="h-1.5 w-1/4 rounded-full bg-[#a9d3fa]" /></div></div><Button onClick={() => setSection("academic")} variant="outline" className="mt-7 w-full rounded-xl border-white bg-white text-[var(--edc-primary)] hover:bg-white">Ir a mis cursos <ArrowUpRight className="ml-2 h-4 w-4" /></Button></CardContent></Card></div><div className="mt-6 rounded-2xl bg-[var(--edc-primary)] p-6 text-white shadow-[0_14px_32px_rgba(31,111,202,0.16)] sm:p-7"><div className="flex flex-col justify-between gap-6 sm:flex-row sm:items-center"><div className="flex items-start gap-4"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-white/15"><Wand2 className="h-5 w-5" /></div><div><p className="text-xs font-semibold uppercase tracking-[0.15em] text-blue-100">Ahorra tiempo</p><h2 className="mt-1 text-xl font-semibold">Crea una actividad con EduCore AI.</h2><p className="mt-1 text-sm text-blue-100">Tema, grado y duración. Tú revisas, editas y decides.</p></div></div><Button onClick={() => setSection("ai")} className="rounded-xl bg-white text-[var(--edc-primary)] hover:bg-blue-50">Crear con IA <Sparkles className="ml-2 h-4 w-4" /></Button></div></div></div>;
}

function StudentDashboard({ data, role, setSection, selectedStudentId, onSelectStudent }: { data: any; role: EduRole; setSection: (s: Section) => void; selectedStudentId?: number; onSelectStudent: (id: number) => void }) {
  const grades = data.grades.slice(0, 5);
  const avg = grades.length ? (grades.reduce((sum: number, item: any) => sum + item.value, 0) / grades.length).toFixed(1) : "4.3";
  const guardianStudentsQuery = trpc.identity.relationships.useQuery({ role }, { enabled: role === "guardian" });
  const currentStudent = guardianStudentsQuery.data?.find((student: any) => student.id === selectedStudentId) ?? data.students?.[0];
  return <div className="editorial-dashboard student-dashboard"><PageHeader eyebrow={role === "guardian" ? "Vista familiar" : "Tu espacio"} title={roleGreetings[role]} detail={role === "guardian" ? `Acompaña el proceso académico de ${currentStudent?.name ?? "tu estudiante"} con una vista simple y accionable.` : "Este es tu resumen para avanzar con claridad esta semana."} action={role === "guardian" ? <select value={selectedStudentId ?? ""} onChange={event => { if (event.target.value) onSelectStudent(Number(event.target.value)); }} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm font-medium text-slate-600"><option value="">Selecciona un estudiante</option>{(guardianStudentsQuery.data ?? []).map((student: any) => <option key={student.id} value={student.id}>{student.name}</option>)}</select> : <Button onClick={() => setSection("ai")} className="rounded-xl bg-[var(--edc-primary)]"><Sparkles className="mr-2 h-4 w-4" />Ask EduCore</Button>} /><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Promedio actual" value={avg} detail="Periodo 2 · sobre 5.0" icon={BarChart3} accent="blue" /><StatCard label="Asistencia" value="96%" detail="1 tardanza este mes" icon={ClipboardCheck} accent="green" /><StatCard label="Por entregar" value={data.assignments.filter((a: any) => a.status !== "Vencida").length} detail="Próximos 8 días" icon={ClipboardList} accent="amber" /></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><Card className="border-0 shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl"><CardHeader><div className="flex items-center justify-between"><div><CardTitle className="text-base">Tu semana</CardTitle><p className="mt-1 text-xs text-slate-400">Lo más importante para los próximos días.</p></div><button onClick={() => setSection("calendar")} className="text-xs font-semibold text-[var(--edc-primary)]">Abrir calendario</button></div></CardHeader><CardContent className="space-y-3">{data.assignments.slice(0, 3).map((item: any, index: number) => <div key={item.id} className="flex items-center gap-3 rounded-xl border border-slate-100 p-3"><div className={`flex h-9 w-9 items-center justify-center rounded-lg ${index === 0 ? "bg-rose-50 text-rose-500" : "bg-[var(--edc-secondary)] text-[var(--edc-accent)]"}`}>{index === 0 ? <Clock3 className="h-4 w-4" /> : <FileText className="h-4 w-4" />}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-slate-700">{item.title}</p><p className="mt-0.5 text-xs text-slate-400">{item.subject} · Entrega {formatDate(item.dueAt)}</p></div><StatusBadge status={item.status} /></div>)}</CardContent></Card><Card className="border-0 bg-white shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl"><CardHeader><div className="flex items-center justify-between"><CardTitle className="text-base">Calificaciones recientes</CardTitle><button onClick={() => setSection("reports")} className="text-xs font-semibold text-[var(--edc-primary)]">Ver todas</button></div></CardHeader><CardContent className="space-y-4">{grades.slice(0, 4).map((item: any) => <div key={item.id} className="flex items-center justify-between"><div><p className="text-sm font-medium text-slate-700">{item.subject}</p><p className="text-xs text-slate-400">{item.period}</p></div><span className={`text-lg font-semibold ${item.value < 3 ? "text-rose-500" : "text-slate-800"}`}>{item.value.toFixed(1)}</span></div>)}{!grades.length ? <EmptyState title="Aún no hay calificaciones" detail="Cuando tus docentes publiquen notas, aparecerán aquí." /> : null}</CardContent></Card></div><button onClick={() => setSection("ai")} className="mt-6 flex w-full items-center gap-4 rounded-2xl border border-[var(--edc-accent)] bg-gradient-to-r from-[#edf7ff] to-white p-5 text-left transition hover:-translate-y-0.5 hover:shadow-[0_10px_25px_rgba(36,117,207,0.1)]"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-[#d7ebff] text-[var(--edc-primary)]"><BrainCircuit className="h-5 w-5" /></div><div className="flex-1"><p className="text-sm font-semibold text-slate-800">Ask EduCore</p><p className="mt-1 text-xs text-slate-500">Pregunta “¿qué tareas tengo pendientes?” o “resume mi semana”.</p></div><ArrowUpRight className="h-5 w-5 text-[var(--edc-accent)]" /></button></div>;
}

function AcademicPage({ data, role, setSection, onGradeSaved }: { data: any; role: EduRole; setSection: (s: Section) => void; onGradeSaved: () => void }) {
  type AcademicTab = "summary" | "courses" | "subjects" | "teachers" | "students" | "enrollments";
  const [tab, setTab] = useState<AcademicTab>("summary");
  const [search, setSearch] = useState("");
  const [showCourseForm, setShowCourseForm] = useState(false);
  const [showSubjectForm, setShowSubjectForm] = useState(false);
  const [courseName, setCourseName] = useState("");
  const [courseCode, setCourseCode] = useState("");
  const [courseCapacity, setCourseCapacity] = useState("32");
  const [gradeId, setGradeId] = useState("");
  const [subjectName, setSubjectName] = useState("");
  const [subjectCode, setSubjectCode] = useState("");
  const [subjectDescription, setSubjectDescription] = useState("");
  const [attachCourseId, setAttachCourseId] = useState("");
  const [attachSubjectId, setAttachSubjectId] = useState("");
  const [enrollCourseId, setEnrollCourseId] = useState("");
  const [assignTeacherId, setAssignTeacherId] = useState("");
  const [assignCourseId, setAssignCourseId] = useState("");
  const [assignSubjectId, setAssignSubjectId] = useState("");
  const [selectedStudentIds, setSelectedStudentIds] = useState<number[]>([]);
  const [transferCourseByEnrollment, setTransferCourseByEnrollment] = useState<Record<number, string>>({});
  const academicQuery = trpc.academic.snapshot.useQuery({ role }, { staleTime: 15_000 });
  const utils = trpc.useUtils();
  const academic = academicQuery.data;
  const refreshAcademic = () => utils.academic.snapshot.invalidate({ role });
  const gradeMutation = trpc.educore.updateGrade.useMutation({ onSuccess: () => { toast.success("Calificación actualizada"); onGradeSaved(); } });
  const createCourseMutation = trpc.academic.createCourse.useMutation({ onSuccess: () => { toast.success("Curso creado"); setShowCourseForm(false); setCourseName(""); setCourseCode(""); refreshAcademic(); }, onError: error => toast.error(error.message) });
  const createSubjectMutation = trpc.academic.createSubject.useMutation({ onSuccess: () => { toast.success("Materia creada"); setShowSubjectForm(false); setSubjectName(""); setSubjectCode(""); setSubjectDescription(""); refreshAcademic(); }, onError: error => toast.error(error.message) });
  const attachMutation = trpc.academic.attachSubject.useMutation({ onSuccess: () => { toast.success("Materia asociada al curso"); refreshAcademic(); }, onError: error => toast.error(error.message) });
  const enrollMutation = trpc.academic.bulkEnroll.useMutation({ onSuccess: () => { toast.success("Matrícula(s) creada(s)"); setSelectedStudentIds([]); refreshAcademic(); }, onError: error => toast.error(error.message) });
  const assignMutation = trpc.academic.assignTeacher.useMutation({ onSuccess: () => { toast.success("Docente asignado"); setAssignTeacherId(""); setAssignCourseId(""); setAssignSubjectId(""); refreshAcademic(); }, onError: error => toast.error(error.message) });
  const transferMutation = trpc.academic.transferStudent.useMutation({ onSuccess: () => { toast.success("Cambio de curso guardado con historial"); refreshAcademic(); }, onError: error => toast.error(error.message) });
  const canManage = role === "admin";
  const activeYear = academic?.activeYear;
  const filteredCourses = (academic?.courses ?? []).filter((course: any) => `${course.name} ${course.code ?? ""}`.toLowerCase().includes(search.toLowerCase()));
  const filteredSubjects = (academic?.subjects ?? []).filter((subject: any) => `${subject.name} ${subject.code ?? ""}`.toLowerCase().includes(search.toLowerCase()));
  const filteredStudents = (academic?.students ?? []).filter((student: any) => `${student.user?.name ?? ""} ${student.studentCode ?? ""}`.toLowerCase().includes(search.toLowerCase()));
  if (academicQuery.isLoading) return <><PageHeader eyebrow="Estructura institucional" title="Académico" detail="Cargando el contexto académico protegido por institución y rol." /><div className="grid gap-4 sm:grid-cols-3"><div className="h-28 animate-pulse rounded-2xl bg-slate-100" /><div className="h-28 animate-pulse rounded-2xl bg-slate-100" /><div className="h-28 animate-pulse rounded-2xl bg-slate-100" /></div></>;
  if (!academic) return <><PageHeader eyebrow="Estructura institucional" title="Académico" detail="No fue posible cargar el contexto académico." /><EmptyState title="Sin contexto académico" detail="Verifica tu membresía institucional o solicita acceso a coordinación." icon={GraduationCap} /></>;
  const tabItems: Array<[AcademicTab, string]> = [["summary", "Resumen"], ["courses", "Cursos"], ["subjects", "Materias"], ["teachers", "Docentes"], ["students", "Estudiantes"], ["enrollments", "Matrículas"]];
  return <>
    <PageHeader eyebrow="Estructura institucional" title="Académico" detail="La fuente de verdad para años, cursos, materias, docentes, estudiantes y matrículas." action={<div className="flex flex-wrap gap-2"><Button onClick={() => setSection("reports")} variant="outline" className="rounded-xl bg-white"><BarChart3 className="mr-2 h-4 w-4" />Ver analítica</Button>{canManage ? <Button onClick={() => setShowCourseForm(true)} className="rounded-xl bg-[var(--edc-primary)]"><Plus className="mr-2 h-4 w-4" />Nuevo curso</Button> : null}</div>} />
    <div className="mb-5 flex flex-col gap-3 rounded-2xl border border-slate-200 bg-white p-3 shadow-sm sm:flex-row sm:items-center"><div className="flex flex-wrap gap-1">{tabItems.map(([value, label]) => <button key={value} onClick={() => setTab(value)} className={`rounded-xl px-3 py-2 text-xs font-semibold transition ${tab === value ? "bg-[var(--edc-secondary)] text-[var(--edc-primary)]" : "text-slate-500 hover:bg-slate-50"}`}>{label}</button>)}</div><div className="ml-auto flex min-w-0 items-center gap-2 rounded-xl border border-slate-200 px-3 py-2 text-xs text-slate-400"><Search className="h-4 w-4 shrink-0" /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Buscar" className="min-w-0 bg-transparent outline-none" /></div></div>
    <div className="mb-5 grid gap-3 sm:grid-cols-3"><div className="rounded-2xl bg-[var(--edc-secondary)] p-4"><p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-400">Año activo</p><p className="mt-2 text-xl font-semibold text-slate-800">{activeYear?.year ?? "—"}</p><p className="mt-1 text-xs text-slate-500">{activeYear?.name ?? "Sin año activo"}</p></div><div className="rounded-2xl border border-slate-200 bg-white p-4"><p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-400">Estructura visible</p><p className="mt-2 text-xl font-semibold text-slate-800">{academic.courses.length} cursos</p><p className="mt-1 text-xs text-slate-500">{academic.subjects.length} materias · {academic.grades.length} grados</p></div><div className="rounded-2xl border border-slate-200 bg-white p-4"><p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-400">Contexto</p><p className="mt-2 text-xl font-semibold text-slate-800">{academic.studentEnrollments.length} activas</p><p className="mt-1 text-xs text-slate-500">Matrículas autorizadas para tu rol</p></div></div>
    {tab === "summary" ? <div className="grid gap-5 xl:grid-cols-[1fr_0.72fr]"><Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Contexto académico visible</CardTitle><p className="mt-1 text-xs text-slate-400">Año → periodo → curso. Este contexto queda listo para calificaciones, asistencia y Classroom.</p></CardHeader><CardContent className="space-y-3">{(academic.periods ?? []).map((period: any) => <div key={period.id} className="flex items-center justify-between rounded-xl border border-slate-100 p-4"><div><p className="text-sm font-semibold text-slate-700">{period.name}</p><p className="mt-1 text-xs text-slate-400">{formatDate(period.startDate)} — {formatDate(period.endDate)}</p></div><StatusBadge status={period.status} /></div>)}{!academic.periods.length ? <EmptyState title="No hay periodos registrados" detail="Un administrador puede crear el calendario académico desde Configuración." /> : null}</CardContent></Card><Card className="surface-card rounded-2xl bg-[var(--edc-secondary)]"><CardContent className="p-6"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-white text-[var(--edc-primary)]"><ShieldCheck className="h-5 w-5" /></div><h2 className="mt-5 text-lg font-semibold text-slate-800">Permisos por contexto</h2><p className="mt-2 text-sm leading-6 text-slate-500">{role === "admin" ? "Puedes gestionar la estructura académica de tu institución." : role === "teacher" ? "Solo ves cursos y materias donde tienes una asignación activa." : "Solo ves tu matrícula o los estudiantes vinculados a tu relación institucional."}</p><div className="mt-5 rounded-xl bg-white/70 p-3 text-xs leading-5 text-slate-500">{academic.years.map((year: any) => `${year.year} · ${year.status}`).join("  ·  ")}</div></CardContent></Card></div> : null}
    {tab === "courses" ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{filteredCourses.map((course: any) => <Card key={course.id} className="surface-card rounded-2xl transition hover:-translate-y-0.5"><CardContent className="p-5"><div className="flex items-start justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[var(--edc-secondary)] text-[var(--edc-accent)]"><BookOpen className="h-5 w-5" /></div><StatusBadge status={course.status} /></div><p className="mt-5 text-lg font-semibold text-slate-800">{course.name}</p><p className="mt-1 text-xs text-slate-400">{course.code ?? "Sin código"} · Grado {course.grade} · {course.year}</p><div className="mt-5 grid grid-cols-3 gap-2 border-t border-slate-100 pt-4"><div><p className="text-[10px] uppercase tracking-wider text-slate-400">Estudiantes</p><p className="mt-1 text-sm font-semibold text-slate-700">{course.studentCount}</p></div><div><p className="text-[10px] uppercase tracking-wider text-slate-400">Materias</p><p className="mt-1 text-sm font-semibold text-slate-700">{course.subjectCount}</p></div><div><p className="text-[10px] uppercase tracking-wider text-slate-400">Docentes</p><p className="mt-1 text-sm font-semibold text-slate-700">{course.teacherCount}</p></div></div><p className="mt-4 text-xs text-slate-400">Capacidad: {course.capacity ?? "No definida"}</p></CardContent></Card>)}{!filteredCourses.length ? <EmptyState title="No hay cursos registrados" detail={canManage ? "Crea un curso para comenzar a estructurar el año académico." : "No hay cursos asignados a tu contexto."} icon={BookOpen} /> : null}</div> : null}
    {tab === "subjects" ? <div className="space-y-5"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{filteredSubjects.map((subject: any) => <Card key={subject.id} className="surface-card rounded-2xl"><CardContent className="p-5"><div className="flex items-start justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-amber-50 text-amber-600"><BookOpen className="h-5 w-5" /></div><span className="text-xs font-semibold text-slate-400">{subject.code ?? "—"}</span></div><p className="mt-5 font-semibold text-slate-800">{subject.name}</p><p className="mt-1 text-xs leading-5 text-slate-400">{subject.description ?? "Materia institucional"}</p><p className="mt-4 text-xs text-slate-500">{academic.courseSubjects.filter((link: any) => link.subjectId === subject.id).length} cursos asociados</p></CardContent></Card>)}{!filteredSubjects.length ? <EmptyState title="No hay materias asociadas" detail={canManage ? "Crea una materia para asociarla a cursos." : "No hay materias en tu contexto."} icon={BookOpen} /> : null}</div>{canManage ? <Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Asociar materia a curso</CardTitle><p className="mt-1 text-xs text-slate-400">Una materia puede vivir en varios cursos, pero nunca cruza instituciones.</p></CardHeader><CardContent className="grid gap-3 sm:grid-cols-[1fr_1fr_auto]"><select value={attachCourseId} onChange={event => setAttachCourseId(event.target.value)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="">Curso</option>{academic.courses.map((course: any) => <option key={course.id} value={course.id}>{course.name}</option>)}</select><select value={attachSubjectId} onChange={event => setAttachSubjectId(event.target.value)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="">Materia</option>{academic.subjects.map((subject: any) => <option key={subject.id} value={subject.id}>{subject.name}</option>)}</select><Button disabled={!attachCourseId || !attachSubjectId || attachMutation.isPending} onClick={() => attachMutation.mutate({ role, courseId: Number(attachCourseId), subjectId: Number(attachSubjectId) })} className="rounded-xl bg-[var(--edc-primary)]">Asociar</Button></CardContent></Card> : null}</div> : null}
    {tab === "teachers" ? <div className="space-y-5"><Card className="surface-card rounded-2xl"><CardHeader><div className="flex items-center justify-between"><div><CardTitle className="text-base">Asignaciones docentes</CardTitle><p className="mt-1 text-xs text-slate-400">Solo se muestran cursos y materias autorizados por asignación.</p></div><Users className="h-5 w-5 text-[var(--edc-accent)]" /></div></CardHeader><CardContent className="space-y-3">{academic.teacherAssignments.map((assignment: any) => <div key={assignment.id} className="flex flex-col gap-2 rounded-xl border border-slate-100 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-semibold text-slate-700">{assignment.teacher?.name ?? "Docente"}</p><p className="mt-1 text-xs text-slate-400">Curso {academic.courses.find((course: any) => course.id === assignment.courseId)?.name ?? "—"} · {academic.subjects.find((subject: any) => subject.id === assignment.subjectId)?.name ?? "—"}</p></div><StatusBadge status={assignment.status} /></div>)}{!academic.teacherAssignments.length ? <EmptyState title="No hay asignaciones docentes" detail="Un administrador puede relacionar un docente con un curso y una materia." icon={Users} /> : null}</CardContent></Card>{canManage ? <Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Nueva asignación</CardTitle><p className="mt-1 text-xs text-slate-400">El docente, curso, materia y año deben pertenecer a la misma institución.</p></CardHeader><CardContent className="grid gap-3 sm:grid-cols-3"><select value={assignTeacherId} onChange={event => setAssignTeacherId(event.target.value)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="">Docente</option>{academic.teachers.map((teacher: any) => <option key={teacher.userId} value={teacher.userId}>{teacher.user?.name ?? "Docente"}</option>)}</select><select value={assignCourseId} onChange={event => setAssignCourseId(event.target.value)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="">Curso</option>{academic.courses.map((course: any) => <option key={course.id} value={course.id}>{course.name}</option>)}</select><select value={assignSubjectId} onChange={event => setAssignSubjectId(event.target.value)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="">Materia</option>{academic.subjects.map((subject: any) => <option key={subject.id} value={subject.id}>{subject.name}</option>)}</select><Button className="rounded-xl bg-[var(--edc-primary)] sm:col-span-3" disabled={!assignTeacherId || !assignCourseId || !assignSubjectId || !activeYear?.id || assignMutation.isPending} onClick={() => assignMutation.mutate({ role, teacherUserId: Number(assignTeacherId), courseId: Number(assignCourseId), subjectId: Number(assignSubjectId), academicYearId: activeYear?.id ?? 0, isPrimary: true })}>Asignar docente</Button></CardContent></Card> : null}</div> : null}
    {tab === "students" ? <Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Estudiantes y contexto de matrícula</CardTitle><p className="mt-1 text-xs text-slate-400">Los perfiles están vinculados a una matrícula, no a una etiqueta de curso aislada.</p></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[640px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wider text-slate-400"><tr><th className="px-5 py-3 font-medium">Estudiante</th><th className="px-5 py-3 font-medium">Código</th><th className="px-5 py-3 font-medium">Grado</th><th className="px-5 py-3 font-medium">Estado</th></tr></thead><tbody>{filteredStudents.map((student: any) => <tr key={student.userId} className="border-t border-slate-100"><td className="px-5 py-4 font-medium text-slate-700">{student.user?.name ?? "Estudiante"}</td><td className="px-5 py-4 text-slate-500">{student.studentCode ?? "—"}</td><td className="px-5 py-4 text-slate-500">{student.gradeLevel ?? "—"}</td><td className="px-5 py-4"><StatusBadge status={student.status} /></td></tr>)}</tbody></table></div>{!filteredStudents.length ? <div className="p-5"><EmptyState title="No hay estudiantes en este contexto" detail="La institución puede crear perfiles e invitaciones desde Usuarios." icon={Users} /></div> : null}</CardContent></Card> : null}
    {tab === "enrollments" ? <div className="space-y-5"><Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Matrícula masiva</CardTitle><p className="mt-1 text-xs text-slate-400">Selecciona varios estudiantes para un curso. La operación mantiene el historial y evita duplicados activos.</p></CardHeader><CardContent><div className="grid gap-3 sm:grid-cols-[1fr_auto]"><select value={enrollCourseId} onChange={event => setEnrollCourseId(event.target.value)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="">Selecciona un curso</option>{academic.courses.map((course: any) => <option key={course.id} value={course.id}>{course.name} · {course.year}</option>)}</select><Button disabled={!canManage || !enrollCourseId || !selectedStudentIds.length || enrollMutation.isPending} onClick={() => enrollMutation.mutate({ role, studentUserIds: selectedStudentIds, academicYearId: activeYear?.id ?? 0, courseId: Number(enrollCourseId) })} className="rounded-xl bg-[var(--edc-primary)]">Matricular {selectedStudentIds.length || ""}</Button></div><div className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{academic.students.map((student: any) => { const id = student.userId; const checked = selectedStudentIds.includes(id); return <label key={id} className={`flex cursor-pointer items-center gap-3 rounded-xl border p-3 text-sm ${checked ? "border-[var(--edc-accent)] bg-[var(--edc-secondary)]" : "border-slate-100"}`}><input type="checkbox" checked={checked} onChange={() => setSelectedStudentIds(current => checked ? current.filter(item => item !== id) : [...current, id])} /><span className="font-medium text-slate-700">{student.user?.name ?? "Estudiante"}</span></label>; })}</div></CardContent></Card><Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Matrículas activas</CardTitle></CardHeader><CardContent className="space-y-3">{academic.studentEnrollments.map((enrollment: any) => <div key={enrollment.id} className="flex flex-col gap-3 rounded-xl border border-slate-100 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-semibold text-slate-700">{enrollment.student?.name ?? "Estudiante"}</p><p className="mt-1 text-xs text-slate-400">Curso actual: {academic.courses.find((course: any) => course.id === enrollment.courseId)?.name ?? "—"}</p></div>{canManage ? <div className="flex items-center gap-2"><select value={transferCourseByEnrollment[enrollment.id] ?? ""} onChange={event => setTransferCourseByEnrollment(current => ({ ...current, [enrollment.id]: event.target.value }))} className="h-9 rounded-lg border border-slate-200 bg-white px-2 text-xs"><option value="">Cambiar curso</option>{academic.courses.filter((course: any) => course.id !== enrollment.courseId).map((course: any) => <option key={course.id} value={course.id}>{course.name}</option>)}</select><Button size="sm" disabled={!transferCourseByEnrollment[enrollment.id] || transferMutation.isPending} onClick={() => transferMutation.mutate({ role, enrollmentId: enrollment.id, newCourseId: Number(transferCourseByEnrollment[enrollment.id]), reason: "Cambio administrativo de curso" })} className="rounded-lg bg-[var(--edc-primary)]">Guardar</Button></div> : null}</div>)}{!academic.studentEnrollments.length ? <EmptyState title="No hay estudiantes matriculados" detail="Un administrador puede usar la matrícula masiva para comenzar." icon={GraduationCap} /> : null}</CardContent></Card></div> : null}
    {showCourseForm ? <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/20 p-4 backdrop-blur-sm" onClick={() => setShowCourseForm(false)}><Card className="w-full max-w-lg rounded-2xl border-0 shadow-2xl" onClick={event => event.stopPropagation()}><CardHeader className="flex flex-row items-start justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-[var(--edc-accent)]">Estructura académica</p><CardTitle className="mt-2">Crear curso</CardTitle></div><button onClick={() => setShowCourseForm(false)} className="rounded-lg p-2 text-slate-400 hover:bg-slate-100"><X className="h-4 w-4" /></button></CardHeader><CardContent className="space-y-4"><label className="block text-sm font-medium text-slate-700">Nombre<Input value={courseName} onChange={event => setCourseName(event.target.value)} placeholder="Ej. 11-3" className="mt-2" /></label><div className="grid gap-4 sm:grid-cols-2"><label className="block text-sm font-medium text-slate-700">Código<Input value={courseCode} onChange={event => setCourseCode(event.target.value)} placeholder="11-3-2026" className="mt-2" /></label><label className="block text-sm font-medium text-slate-700">Capacidad<Input type="number" value={courseCapacity} onChange={event => setCourseCapacity(event.target.value)} className="mt-2" /></label></div><label className="block text-sm font-medium text-slate-700">Grado<select value={gradeId} onChange={event => setGradeId(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="">Selecciona un grado</option>{academic.grades.map((grade: any) => <option key={grade.id} value={grade.id}>{grade.name} · {grade.shortName}</option>)}</select></label><Button disabled={!courseName || !courseCode || !gradeId || !activeYear?.id || createCourseMutation.isPending} onClick={() => createCourseMutation.mutate({ role, academicYearId: activeYear?.id ?? 0, gradeLevelId: Number(gradeId), name: courseName, code: courseCode, capacity: Number(courseCapacity) || null })} className="w-full rounded-xl bg-[var(--edc-primary)]">{createCourseMutation.isPending ? "Guardando..." : "Crear curso"}</Button><button onClick={() => { setShowCourseForm(false); setShowSubjectForm(true); }} className="w-full text-xs font-semibold text-[var(--edc-primary)]">¿Necesitas crear una materia primero?</button></CardContent></Card></div> : null}
    {showSubjectForm ? <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/20 p-4 backdrop-blur-sm" onClick={() => setShowSubjectForm(false)}><Card className="w-full max-w-lg rounded-2xl border-0 shadow-2xl" onClick={event => event.stopPropagation()}><CardHeader className="flex flex-row items-start justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-[var(--edc-accent)]">Catálogo institucional</p><CardTitle className="mt-2">Crear materia</CardTitle></div><button onClick={() => setShowSubjectForm(false)} className="rounded-lg p-2 text-slate-400 hover:bg-slate-100"><X className="h-4 w-4" /></button></CardHeader><CardContent className="space-y-4"><label className="block text-sm font-medium text-slate-700">Nombre<Input value={subjectName} onChange={event => setSubjectName(event.target.value)} placeholder="Ej. Biología" className="mt-2" /></label><label className="block text-sm font-medium text-slate-700">Código<Input value={subjectCode} onChange={event => setSubjectCode(event.target.value)} placeholder="BIO" className="mt-2" /></label><label className="block text-sm font-medium text-slate-700">Descripción<Textarea value={subjectDescription} onChange={event => setSubjectDescription(event.target.value)} placeholder="Descripción breve" className="mt-2 min-h-24" /></label><Button disabled={!subjectName || !subjectCode || createSubjectMutation.isPending} onClick={() => createSubjectMutation.mutate({ role, name: subjectName, shortName: subjectName.slice(0, 3).toUpperCase(), code: subjectCode, description: subjectDescription })} className="w-full rounded-xl bg-[var(--edc-primary)]">{createSubjectMutation.isPending ? "Guardando..." : "Crear materia"}</Button></CardContent></Card></div> : null}
  </>;
}
function GradeBook({ data, role, mutation }: { data: any; role: EduRole; mutation: any }) {
  const [course, setCourse] = useState("11-2");
  const [subject, setSubject] = useState("Matemáticas");
  const gradeRows = data.grades.filter((grade: any) => grade.course === course && grade.subject === subject);
  return <Card className="border-0 shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl"><CardHeader><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><CardTitle className="text-base">Ingreso rápido de notas</CardTitle><p className="mt-1 text-xs text-slate-400">Edita directamente desde la tabla. Los cambios quedan registrados.</p></div><div className="flex gap-2"><select value={course} onChange={event => setCourse(event.target.value)} className="h-9 rounded-lg border border-slate-200 bg-white px-2 text-xs"><option>11-2</option><option>11-1</option></select><select value={subject} onChange={event => setSubject(event.target.value)} className="h-9 rounded-lg border border-slate-200 bg-white px-2 text-xs"><option>Matemáticas</option><option>Física</option><option>Química</option></select></div></div></CardHeader><CardContent><div className="mb-4 grid grid-cols-3 gap-3"><div className="rounded-xl bg-slate-50 p-3"><p className="text-[10px] uppercase tracking-wider text-slate-400">Promedio</p><p className="mt-1 text-lg font-semibold text-slate-800">{gradeRows.length ? (gradeRows.reduce((s: number, g: any) => s + g.value, 0) / gradeRows.length).toFixed(1) : "—"}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[10px] uppercase tracking-wider text-slate-400">Máximo</p><p className="mt-1 text-lg font-semibold text-slate-800">{gradeRows.length ? Math.max(...gradeRows.map((g: any) => g.value)).toFixed(1) : "—"}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[10px] uppercase tracking-wider text-slate-400">Mínimo</p><p className="mt-1 text-lg font-semibold text-slate-800">{gradeRows.length ? Math.min(...gradeRows.map((g: any) => g.value)).toFixed(1) : "—"}</p></div></div><div className="overflow-x-auto"><table className="w-full min-w-[560px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wider text-slate-400"><tr><th className="rounded-l-lg px-4 py-3 font-medium">Estudiante</th><th className="px-4 py-3 font-medium">Periodo</th><th className="px-4 py-3 font-medium">Nota</th><th className="rounded-r-lg px-4 py-3 font-medium">Estado</th></tr></thead><tbody>{gradeRows.map((grade: any) => <GradeRow key={grade.id} grade={grade} role={role} mutation={mutation} />)}</tbody></table></div>{!gradeRows.length ? <EmptyState title="No hay notas para este filtro" detail="Prueba con otro curso o materia." /> : null}</CardContent></Card>;
}

function GradeRow({ grade, role, mutation }: { grade: any; role: EduRole; mutation: any }) {
  const [value, setValue] = useState(String(grade.value));
  return <tr className="border-t border-slate-100"><td className="px-4 py-4 font-medium text-slate-700">{grade.studentName}</td><td className="px-4 py-4 text-slate-500">{grade.period}</td><td className="px-4 py-4"><input aria-label={`Nota de ${grade.studentName}`} value={value} onChange={event => setValue(event.target.value)} onBlur={() => { const parsed = Number(value); if (parsed >= 0 && parsed <= 5 && parsed !== grade.value) mutation.mutate({ role, studentName: grade.studentName, course: grade.course, subject: grade.subject, period: grade.period, value: parsed }); }} className="h-8 w-16 rounded-lg border border-slate-200 px-2 text-center text-sm font-semibold text-slate-800 outline-none focus:border-[#368de8] focus:ring-2 focus:ring-[#dceeff]" /></td><td className="px-4 py-4"><span className={`inline-flex items-center gap-1 text-xs font-medium ${grade.value < 3 ? "text-rose-600" : "text-emerald-600"}`}>{grade.value < 3 ? <AlertCircle className="h-3.5 w-3.5" /> : <CheckCircle2 className="h-3.5 w-3.5" />}{grade.value < 3 ? "Requiere seguimiento" : "En buen camino"}</span></td></tr>;
}

function ClassroomPage({ data, role, onChanged, setSection }: { data: any; role: EduRole; onChanged: () => void; setSection: (s: Section) => void }) {
  const [showCreate, setShowCreate] = useState(false);
  const [selectedAssignment, setSelectedAssignment] = useState<any>(null);
  const [title, setTitle] = useState(""); const [subject, setSubject] = useState("Matemáticas"); const [course, setCourse] = useState("11-2"); const [description, setDescription] = useState(""); const [dueAt, setDueAt] = useState(todayInput());
  const createMutation = trpc.educore.createAssignment.useMutation({ onSuccess: () => { toast.success("Tarea creada y publicada"); setShowCreate(false); setTitle(""); setDescription(""); onChanged(); } });
  const submitMutation = trpc.educore.submitAssignment.useMutation({ onSuccess: () => { toast.success("Entrega enviada"); setSelectedAssignment(null); onChanged(); } });
  return <><PageHeader eyebrow="EduCore Classroom" title="Aprender también es entregar." detail="Diseña actividades, acompaña el proceso y mantén cada evidencia en contexto." action={role === "admin" || role === "teacher" ? <Button onClick={() => setShowCreate(true)} className="rounded-xl bg-[var(--edc-primary)]"><Plus className="mr-2 h-4 w-4" />Crear tarea</Button> : null} /><div className="mb-5 flex items-center justify-between rounded-2xl bg-[var(--edc-secondary)] p-4"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-white text-[var(--edc-accent)]"><ClipboardList className="h-4 w-4" /></div><div><p className="text-sm font-semibold text-slate-700">{role === "teacher" ? "Tu actividad docente" : role === "admin" ? "Actividad del colegio" : "Tus próximas actividades"}</p><p className="mt-0.5 text-xs text-slate-500">{data.assignments.length} tareas · {data.submissions.length} entregas registradas</p></div></div><button onClick={() => setSection("ai")} className="hidden items-center gap-1 text-xs font-semibold text-[var(--edc-primary)] sm:flex">Crear con IA <Sparkles className="h-3.5 w-3.5" /></button></div><div className="grid gap-4 lg:grid-cols-2">{data.assignments.map((assignment: any) => { const submission = data.submissions.find((item: any) => item.assignmentId === assignment.id); return <Card key={assignment.id} className="border-0 shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl transition hover:-translate-y-0.5"><CardContent className="p-5"><div className="flex items-start justify-between gap-4"><div className="flex items-start gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[var(--edc-secondary)] text-[var(--edc-accent)]"><FileText className="h-5 w-5" /></div><div><p className="font-semibold text-slate-800">{assignment.title}</p><p className="mt-1 text-xs text-slate-400">{assignment.subject} · {assignment.course}</p></div></div><StatusBadge status={submission?.grade ? "Calificada" : submission?.status ?? assignment.status} /></div><p className="mt-5 line-clamp-2 text-sm leading-6 text-slate-500">{assignment.description}</p><div className="mt-5 flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 pt-4"><div className="flex items-center gap-3 text-xs text-slate-400"><span className="flex items-center gap-1"><Clock3 className="h-3.5 w-3.5" />{formatDate(assignment.dueAt)}</span><span>{assignment.points} puntos</span></div>{role === "student" || role === "guardian" ? <Button onClick={() => setSelectedAssignment(assignment)} size="sm" className="rounded-lg bg-[var(--edc-primary)]">{submission ? "Ver entrega" : "Entregar"}</Button> : <Button onClick={() => setSelectedAssignment(assignment)} size="sm" variant="outline" className="rounded-lg bg-white">Ver entregas <ChevronRight className="ml-1 h-3.5 w-3.5" /></Button>}</div></CardContent></Card>; })}</div>{showCreate ? <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/20 p-4 backdrop-blur-sm"><Card className="max-h-[90vh] w-full max-w-xl overflow-y-auto border-0 shadow-2xl rounded-2xl"><CardHeader className="flex flex-row items-start justify-between"><div><CardTitle>Crear tarea</CardTitle><p className="mt-1 text-xs text-slate-400">Publica una actividad para que tus estudiantes puedan verla y entregar.</p></div><button onClick={() => setShowCreate(false)} className="rounded-lg p-1 text-slate-400 hover:bg-slate-100"><X className="h-4 w-4" /></button></CardHeader><CardContent className="space-y-4"><label className="block text-sm font-medium text-slate-700">Título<Input value={title} onChange={event => setTitle(event.target.value)} placeholder="Ej. Taller de derivadas" className="mt-2" /></label><div className="grid gap-4 sm:grid-cols-2"><label className="block text-sm font-medium text-slate-700">Materia<select value={subject} onChange={event => setSubject(event.target.value)} className="mt-2 h-10 w-full rounded-md border border-slate-200 bg-white px-3 text-sm"><option>Matemáticas</option><option>Física</option><option>Filosofía</option><option>Inglés</option></select></label><label className="block text-sm font-medium text-slate-700">Curso<select value={course} onChange={event => setCourse(event.target.value)} className="mt-2 h-10 w-full rounded-md border border-slate-200 bg-white px-3 text-sm"><option>11-2</option><option>11-1</option><option>10-1</option></select></label></div><label className="block text-sm font-medium text-slate-700">Instrucciones<Textarea value={description} onChange={event => setDescription(event.target.value)} placeholder="Explica lo que deben realizar..." className="mt-2 min-h-28" /></label><div className="grid gap-4 sm:grid-cols-2"><label className="block text-sm font-medium text-slate-700">Fecha de entrega<Input type="datetime-local" value={dueAt} onChange={event => setDueAt(event.target.value)} className="mt-2" /></label><label className="block text-sm font-medium text-slate-700">Puntuación<Input type="number" defaultValue={100} className="mt-2" /></label></div><div className="flex items-center justify-between rounded-xl bg-[var(--edc-secondary)] p-3 text-xs text-slate-500"><span className="flex items-center gap-2"><Sparkles className="h-4 w-4 text-[var(--edc-accent)]" />¿Prefieres empezar con un borrador?</span><button onClick={() => { setShowCreate(false); setSection("ai"); }} className="font-semibold text-[var(--edc-primary)]">Crear con IA</button></div><Button disabled={!title || !description || createMutation.isPending} onClick={() => createMutation.mutate({ role, title, subject, course, description, dueAt: new Date(dueAt), points: 100, teacherName: "Laura Gómez" })} className="w-full rounded-xl bg-[var(--edc-primary)]">{createMutation.isPending ? "Guardando..." : "Publicar tarea"}</Button></CardContent></Card></div> : null}{selectedAssignment ? <SubmissionModal assignment={selectedAssignment} role={role} data={data} onClose={() => setSelectedAssignment(null)} onSubmit={(fileName, comment) => submitMutation.mutate({ role, assignmentId: selectedAssignment.id, studentName: "Sofía Martínez", fileName, comment })} /> : null}</>;
}

function SubmissionModal({ assignment, role, data, onClose, onSubmit }: { assignment: any; role: EduRole; data: any; onClose: () => void; onSubmit: (fileName: string, comment: string) => void }) {
  const existing = data.submissions.find((item: any) => item.assignmentId === assignment.id);
  const [fileName, setFileName] = useState(existing?.fileName ?? ""); const [comment, setComment] = useState(existing?.comment ?? "");
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/20 p-4 backdrop-blur-sm"><Card className="w-full max-w-lg border-0 shadow-2xl rounded-2xl"><CardHeader className="flex flex-row items-start justify-between"><div><CardTitle>{assignment.title}</CardTitle><p className="mt-1 text-xs text-slate-400">{assignment.subject} · Entrega {formatDate(assignment.dueAt)}</p></div><button onClick={onClose} className="rounded-lg p-1 text-slate-400 hover:bg-slate-100"><X className="h-4 w-4" /></button></CardHeader><CardContent><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-semibold uppercase tracking-wider text-slate-400">Instrucciones</p><p className="mt-2 text-sm leading-6 text-slate-600">{assignment.description}</p></div>{role === "student" || role === "guardian" ? <div className="mt-5 space-y-4"><label className="block text-sm font-medium text-slate-700">Archivo de entrega<div className="mt-2 flex items-center gap-2"><Input value={fileName} onChange={event => setFileName(event.target.value)} placeholder="Selecciona o escribe un archivo" /><button onClick={() => setFileName("taller-derivadas-sofia.pdf")} className="flex h-10 shrink-0 items-center gap-2 rounded-md border border-slate-200 px-3 text-xs font-medium text-slate-600 hover:bg-slate-50"><Upload className="h-4 w-4" />Adjuntar</button></div></label><label className="block text-sm font-medium text-slate-700">Comentario<Textarea value={comment} onChange={event => setComment(event.target.value)} placeholder="Agrega una nota para tu docente..." className="mt-2" /></label><Button disabled={!fileName} onClick={() => onSubmit(fileName, comment)} className="w-full rounded-xl bg-[var(--edc-primary)]"><Send className="mr-2 h-4 w-4" />Enviar entrega</Button></div> : <div className="mt-5"><p className="text-xs font-semibold uppercase tracking-wider text-slate-400">Entregas recibidas</p>{data.submissions.filter((item: any) => item.assignmentId === assignment.id).map((submission: any) => <div key={submission.id} className="mt-3 flex items-center gap-3 rounded-xl border border-slate-100 p-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[var(--edc-secondary)] text-[var(--edc-accent)]"><FileText className="h-4 w-4" /></div><div className="flex-1"><p className="text-sm font-medium text-slate-700">{submission.studentName}</p><p className="text-xs text-slate-400">{submission.fileName} · {formatDateTime(submission.submittedAt)}</p></div>{submission.grade ? <span className="font-semibold text-emerald-600">{submission.grade.toFixed(1)}</span> : <span className="text-xs text-amber-600">Por calificar</span>}</div>)}</div>}</CardContent></Card></div>;
}

function AttendancePage({ data, role, onChanged }: { data: any; role: EduRole; onChanged: () => void }) {
  const canEdit = role === "admin" || role === "teacher";
  const [course, setCourse] = useState("11-2"); const [statuses, setStatuses] = useState<Record<string, string>>({});
  const attendanceMutation = trpc.educore.recordAttendance.useMutation({ onSuccess: () => { toast.success("Asistencia registrada"); onChanged(); } });
  const students = data.students.filter((student: any) => student.course === course);
  const setStatus = (name: string, status: string) => setStatuses(prev => ({ ...prev, [name]: status }));
  return <><PageHeader eyebrow="Control diario" title="Asistencia" detail="Registra presente, ausente, tardanza o excusa en pocos clics." action={canEdit ? <Button onClick={() => attendanceMutation.mutate({ role, course, date: new Date(), records: students.map((student: any) => ({ studentName: student.name, status: (statuses[student.name] ?? "Presente") as "Presente" | "Ausente" | "Tardanza" | "Excusa" })) })} className="rounded-xl bg-[var(--edc-primary)]"><Check className="mr-2 h-4 w-4" />Guardar asistencia</Button> : null} /><div className="mb-5 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div><p className="text-sm font-semibold text-slate-700">{course} · {formatDate(new Date(), { weekday: "long", day: "numeric", month: "long" })}</p><p className="mt-1 text-xs text-slate-400">{students.length || 6} estudiantes en la lista de hoy</p></div><select value={course} onChange={event => setCourse(event.target.value)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-xs"><option>11-2</option><option>11-1</option><option>10-1</option></select></div><div className="grid gap-5 lg:grid-cols-[1fr_0.8fr]"><Card className="border-0 shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl"><CardContent className="p-3">{students.length ? students.map((student: any) => { const status = statuses[student.name] ?? data.attendance.find((row: any) => row.studentName === student.name)?.status ?? "Presente"; return <div key={student.id} className="flex flex-col gap-3 border-b border-slate-100 p-3 last:border-0 sm:flex-row sm:items-center"><div className="flex flex-1 items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-full text-[11px] font-semibold text-slate-700" style={{ backgroundColor: student.avatarColor }}>{initials(student.name)}</div><div><p className="text-sm font-medium text-slate-700">{student.name}</p><p className="text-xs text-slate-400">{student.course}</p></div></div><div className="grid grid-cols-4 gap-1 rounded-xl bg-slate-50 p-1">{["Presente", "Ausente", "Tardanza", "Excusa"].map(option => <button disabled={!canEdit} key={option} onClick={() => setStatus(student.name, option)} className={`rounded-lg px-2 py-1.5 text-[11px] font-medium transition ${status === option ? option === "Presente" ? "bg-emerald-100 text-emerald-700" : option === "Ausente" ? "bg-rose-100 text-rose-700" : "bg-amber-100 text-amber-700" : "text-slate-400 hover:bg-white"}`}>{option}</button>)}</div></div>; }) : <EmptyState title="No hay estudiantes para este curso" detail="Selecciona otro curso para registrar asistencia." icon={Users} />}</CardContent></Card><Card className="border-0 bg-[var(--edc-secondary)] shadow-none rounded-2xl"><CardContent className="p-6"><p className="text-xs font-semibold uppercase tracking-[0.14em] text-[var(--edc-primary)]">Resumen del mes</p><div className="mt-7 text-center"><div className="mx-auto flex h-32 w-32 items-center justify-center rounded-full border-[10px] border-white text-3xl font-semibold text-slate-800 shadow-sm"><span>94<span className="text-base">%</span></span></div><p className="mt-4 text-sm font-semibold text-slate-700">Asistencia general</p><p className="mt-1 text-xs text-slate-500">+2.4% frente al mes anterior</p></div><div className="mt-8 space-y-3"><div className="flex items-center justify-between text-xs"><span className="text-slate-500">Presentes</span><span className="font-semibold text-emerald-600">94%</span></div><div className="flex items-center justify-between text-xs"><span className="text-slate-500">Tardanzas</span><span className="font-semibold text-amber-600">3%</span></div><div className="flex items-center justify-between text-xs"><span className="text-slate-500">Ausencias</span><span className="font-semibold text-rose-600">3%</span></div></div></CardContent></Card></div></>;
}

function CalendarPage({ data }: { data: any }) {
  return <><PageHeader eyebrow="Agenda institucional" title="Calendario" detail="Una vista compartida de clases, evaluaciones y momentos importantes." action={<Button onClick={() => toast.success("Evento demo creado. Puedes conectarlo a tu calendario institucional.")} className="rounded-xl bg-[var(--edc-primary)]"><Plus className="mr-2 h-4 w-4" />Nuevo evento</Button>} /><div className="grid gap-5 xl:grid-cols-[1fr_320px]"><Card className="border-0 shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl"><CardHeader><div className="flex items-center justify-between"><div><CardTitle className="text-base">Septiembre 2026</CardTitle><p className="mt-1 text-xs text-slate-400">Semana del 14 al 20 de septiembre</p></div><div className="flex gap-1"><button className="rounded-lg border border-slate-200 p-2 text-slate-400 hover:bg-slate-50">‹</button><button className="rounded-lg border border-slate-200 p-2 text-slate-400 hover:bg-slate-50">›</button></div></div></CardHeader><CardContent><div className="grid grid-cols-7 gap-1 text-center text-[10px] font-semibold uppercase tracking-wider text-slate-400">{["Lun", "Mar", "Mié", "Jue", "Vie", "Sáb", "Dom"].map(day => <div key={day} className="py-2">{day}</div>)}</div><div className="grid grid-cols-7 gap-1">{Array.from({ length: 35 }).map((_, index) => { const day = index - 1; const hasEvent = [3, 6, 12, 18].includes(day); return <div key={index} className={`min-h-20 rounded-xl border p-2 text-left ${day === 15 ? "border-[#89c5fa] bg-[var(--edc-secondary)]" : "border-slate-100 bg-white"}`}><span className={`text-xs ${day === 15 ? "font-bold text-[var(--edc-primary)]" : "text-slate-500"}`}>{day > 0 && day < 31 ? day : ""}</span>{hasEvent ? <div className="mt-2 space-y-1"><span className="block truncate rounded bg-rose-50 px-1 py-0.5 text-[9px] font-medium text-rose-600">{day === 3 ? "Evaluación" : day === 6 ? "Reunión" : day === 12 ? "Feria" : "Cierre"}</span></div> : null}</div>; })}</div></CardContent></Card><Card className="border-0 shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl"><CardHeader><CardTitle className="text-base">Próximos eventos</CardTitle></CardHeader><CardContent className="space-y-4">{data.events.slice(0, 4).map((event: any) => <div key={event.id} className="flex gap-3"><div className="flex w-11 flex-col items-center rounded-xl bg-[var(--edc-secondary)] py-2 text-[var(--edc-primary)]"><span className="text-[10px] font-semibold uppercase">{new Date(event.eventDate).toLocaleDateString("es-CO", { month: "short" })}</span><span className="text-lg font-semibold">{new Date(event.eventDate).getDate()}</span></div><div><p className="text-sm font-semibold text-slate-700">{event.title}</p><p className="mt-1 text-xs text-slate-400">{event.type} · {event.location}</p></div></div>)}</CardContent></Card></div></>;
}

function CommunicationsPage({ data, role, onChanged }: { data: any; role: EduRole; onChanged: () => void }) {
  const [showCompose, setShowCompose] = useState(false); const [title, setTitle] = useState(""); const [message, setMessage] = useState("");
  const aiMutation = trpc.educore.generateDraft.useMutation({ onSuccess: result => { setMessage(result.text); toast.success("Borrador generado. Revísalo antes de publicar."); } });
  return <><PageHeader eyebrow="Comunidad" title="Comunicaciones" detail="Mantén a cada persona informada con mensajes claros, oportunos y segmentados." action={role === "admin" ? <Button onClick={() => setShowCompose(true)} className="rounded-xl bg-[var(--edc-primary)]"><Plus className="mr-2 h-4 w-4" />Nuevo comunicado</Button> : null} /><div className="mb-5 grid gap-3 sm:grid-cols-3"><div className="rounded-2xl border border-slate-200 bg-white p-4"><p className="text-xs text-slate-400">Publicados</p><p className="mt-2 text-2xl font-semibold text-slate-800">{data.announcements.filter((a: any) => a.status === "Publicado").length}</p></div><div className="rounded-2xl border border-slate-200 bg-white p-4"><p className="text-xs text-slate-400">Borradores</p><p className="mt-2 text-2xl font-semibold text-slate-800">{data.announcements.filter((a: any) => a.status === "Borrador").length}</p></div><div className="rounded-2xl border border-slate-200 bg-white p-4"><p className="text-xs text-slate-400">Audiencia</p><p className="mt-2 text-2xl font-semibold text-slate-800">Toda la comunidad</p></div></div><div className="space-y-3">{data.announcements.map((item: any) => <Card key={item.id} className="border-0 shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl"><CardContent className="flex flex-col gap-4 p-5 sm:flex-row sm:items-start"><div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[var(--edc-secondary)] text-[var(--edc-accent)]"><Megaphone className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex flex-col justify-between gap-2 sm:flex-row"><div><div className="flex items-center gap-2"><p className="font-semibold text-slate-800">{item.title}</p><StatusBadge status={item.status} /></div><p className="mt-1 text-xs text-slate-400">Para: {item.audience} · {formatDate(item.publishedAt)}</p></div><button onClick={() => toast.success("Acción disponible en el siguiente flujo de publicación.")} className="self-start rounded-lg p-2 text-slate-400 hover:bg-slate-50"><MoreHorizontal className="h-4 w-4" /></button></div><p className="mt-4 text-sm leading-6 text-slate-500">{item.message}</p></div></CardContent></Card>)}</div>{showCompose ? <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/20 p-4 backdrop-blur-sm"><Card className="w-full max-w-xl border-0 shadow-2xl rounded-2xl"><CardHeader className="flex flex-row items-start justify-between"><div><CardTitle>Nuevo comunicado</CardTitle><p className="mt-1 text-xs text-slate-400">Escribe, revisa y publica cuando estés listo.</p></div><button onClick={() => setShowCompose(false)} className="rounded-lg p-1 text-slate-400 hover:bg-slate-100"><X className="h-4 w-4" /></button></CardHeader><CardContent className="space-y-4"><label className="block text-sm font-medium text-slate-700">Título<Input value={title} onChange={event => setTitle(event.target.value)} placeholder="Ej. Reunión de padres" className="mt-2" /></label><label className="block text-sm font-medium text-slate-700">Mensaje<Textarea value={message} onChange={event => setMessage(event.target.value)} placeholder="Escribe el mensaje para la comunidad..." className="mt-2 min-h-32" /></label><button disabled={aiMutation.isPending} onClick={() => aiMutation.mutate({ role, kind: "communication", prompt: title || "Reunión de padres de 11°", context: message })} className="flex items-center gap-2 text-xs font-semibold text-[var(--edc-primary)]"><Sparkles className="h-4 w-4" />{aiMutation.isPending ? "Redactando..." : "Redactar con EduCore AI"}</button><div className="grid gap-4 sm:grid-cols-2"><label className="block text-sm font-medium text-slate-700">Destinatarios<select className="mt-2 h-10 w-full rounded-md border border-slate-200 bg-white px-3 text-sm"><option>Todo el colegio</option><option>Acudientes de 11°</option><option>Docentes</option><option>Estudiantes</option></select></label><label className="block text-sm font-medium text-slate-700">Estado<select className="mt-2 h-10 w-full rounded-md border border-slate-200 bg-white px-3 text-sm"><option>Publicado</option><option>Borrador</option><option>Programado</option></select></label></div><Button disabled={!title || !message} onClick={() => { toast.success("Comunicado guardado como borrador demo."); setShowCompose(false); onChanged(); }} className="w-full rounded-xl bg-[var(--edc-primary)]"><Send className="mr-2 h-4 w-4" />Guardar comunicado</Button></CardContent></Card></div> : null}</>;
}

function ReportsPage({ data, role, setSection }: { data: any; role: EduRole; setSection: (s: Section) => void }) {
  const aiMutation = trpc.educore.generateDraft.useMutation({ onSuccess: result => toast.success("Análisis generado en EduCore AI.") });
  const avgByCourse = data.courses.map((course: any) => ({ ...course, pct: Math.round(course.average / 5 * 100) }));
  return <><PageHeader eyebrow="Lectura de datos" title="Reportes y analítica" detail="Encuentra tendencias sin perder de vista a las personas detrás de los datos." action={<Button onClick={() => toast.success("Boletín demo preparado para descarga.")} variant="outline" className="rounded-xl bg-white"><Download className="mr-2 h-4 w-4" />Generar boletines</Button>} /><div className="grid gap-5 xl:grid-cols-[1fr_0.75fr]"><Card className="border-0 shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl"><CardHeader><CardTitle className="text-base">Promedio por curso</CardTitle><p className="mt-1 text-xs text-slate-400">Periodo 2 · escala de 5.0</p></CardHeader><CardContent className="space-y-5">{avgByCourse.map((course: any) => <div key={course.id}><div className="mb-2 flex items-center justify-between text-sm"><span className="font-medium text-slate-700">{course.name}</span><span className="font-semibold text-slate-800">{course.average.toFixed(1)}</span></div><div className="h-2 rounded-full bg-slate-100"><div style={{ width: `${course.pct}%` }} className={`h-2 rounded-full ${course.average < 3.5 ? "bg-rose-400" : "bg-[#58a5ee]"}`} /></div></div>)}</CardContent></Card><Card className="border-0 bg-[var(--edc-secondary)] shadow-none rounded-2xl"><CardContent className="p-6"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-white text-[var(--edc-accent)]"><BrainCircuit className="h-5 w-5" /></div><p className="mt-6 text-xs font-semibold uppercase tracking-[0.14em] text-[var(--edc-primary)]">Lectura asistida</p><h2 className="mt-2 text-xl font-semibold leading-7 text-slate-800">Hay una oportunidad de seguimiento en 11-1.</h2><p className="mt-2 text-sm leading-6 text-slate-500">El promedio está 0.3 puntos debajo del resto de los cursos de grado 11. Revisa las materias con mayor dispersión.</p><Button onClick={() => { aiMutation.mutate({ role, kind: "insight", prompt: "Analiza el rendimiento de 11-1", context: JSON.stringify(data.grades) }); setSection("ai"); }} className="mt-6 rounded-xl bg-white text-[var(--edc-primary)] hover:bg-white">Pedir análisis a AI <Sparkles className="ml-2 h-4 w-4" /></Button></CardContent></Card></div><div className="mt-6 grid gap-5 lg:grid-cols-2"><Card className="border-0 shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl"><CardHeader><CardTitle className="text-base">Estudiantes con dificultades</CardTitle></CardHeader><CardContent className="space-y-3">{data.grades.filter((grade: any) => grade.value < 3.5).map((grade: any) => <div key={grade.id} className="flex items-center justify-between rounded-xl bg-rose-50/60 p-3"><div><p className="text-sm font-semibold text-slate-700">{grade.studentName}</p><p className="text-xs text-slate-500">{grade.course} · {grade.subject}</p></div><span className="font-semibold text-rose-600">{grade.value.toFixed(1)}</span></div>)}<p className="pt-2 text-xs text-slate-400">Estas señales son informativas. La decisión pedagógica siempre permanece con el equipo autorizado.</p></CardContent></Card><Card className="border-0 shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl"><CardHeader><div className="flex items-center justify-between"><CardTitle className="text-base">Boletines</CardTitle><button onClick={() => toast.success("Vista previa de boletines lista.")} className="text-xs font-semibold text-[var(--edc-primary)]">Previsualizar</button></div></CardHeader><CardContent className="space-y-3">{data.reportCards.map((card: any) => <div key={card.id} className="flex items-center justify-between rounded-xl border border-slate-100 p-3"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-violet-50 text-violet-600"><FileText className="h-4 w-4" /></div><div><p className="text-sm font-semibold text-slate-700">{card.studentName}</p><p className="text-xs text-slate-400">{card.course} · {card.period}</p></div></div><div className="text-right"><p className="text-sm font-semibold text-slate-800">{card.average.toFixed(1)}</p><p className="text-[11px] text-emerald-600">{card.status}</p></div></div>)}</CardContent></Card></div></>;
}

function AiPage({ data, role }: { data: any; role: EduRole }) {
  const [kind, setKind] = useState<"activity" | "communication" | "planning" | "insight">(role === "student" || role === "guardian" ? "insight" : "activity");
  const [prompt, setPrompt] = useState(role === "student" ? "¿Qué tareas tengo pendientes esta semana?" : "Derivadas para grado 11, dificultad media, 45 minutos");
  const [result, setResult] = useState("");
  const mutation = trpc.educore.generateDraft.useMutation({ onSuccess: value => { setResult(value.text); toast.success("EduCore AI preparó un borrador para revisión."); }, onError: () => { setResult(`## Resumen contextual\n\nPara tu consulta “${prompt}”, revisa las actividades visibles en tu espacio y prioriza las fechas más próximas. Esta sugerencia es informativa y no sustituye la orientación de tu docente o institución.`); toast.info("Mostrando una respuesta local mientras EduCore AI se conecta."); } });
  const isLearner = role === "student" || role === "guardian";
  const submit = () => mutation.mutate({ role, kind, prompt, context: JSON.stringify({ assignments: data.assignments, grades: data.grades, attendance: data.attendance }) });
  return <div className="ai-workspace"><PageHeader eyebrow="Inteligencia contextual" title="EduCore AI" detail="Una capa de ayuda dentro de tu trabajo, con permisos y revisión humana en cada decisión." action={<div className="flex items-center gap-2 rounded-xl bg-[var(--edc-secondary)] px-3 py-2 text-xs font-medium text-[var(--edc-primary)]"><ShieldCheck className="h-4 w-4" />Respetando tu rol</div>} /><div className="grid gap-5 xl:grid-cols-[0.75fr_1.25fr]"><Card className="border-0 bg-[var(--edc-primary)] text-white shadow-[0_14px_32px_rgba(31,111,202,0.22)] rounded-2xl"><CardContent className="p-6"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-white/15"><Sparkles className="h-5 w-5" /></div><h2 className="mt-7 text-2xl font-semibold leading-8">Tu copiloto para menos administración.</h2><p className="mt-3 text-sm leading-6 text-blue-100">Genera borradores, resume información y encuentra señales. EduCore AI no publica ni decide por ti.</p><div className="mt-8 space-y-2">{(isLearner ? ["¿Qué tareas tengo pendientes?", "Resume mi semana", "¿Cómo va mi asistencia?"] : ["Crea una actividad de derivadas", "Redacta un comunicado", "Analiza el rendimiento de 11-2"]).map(suggestion => <button key={suggestion} onClick={() => setPrompt(suggestion)} className="flex w-full items-center justify-between rounded-xl bg-white/10 px-3 py-3 text-left text-xs text-blue-50 transition hover:bg-white/15"><span>{suggestion}</span><ArrowUpRight className="h-3.5 w-3.5" /></button>)}</div></CardContent></Card><Card className="border-0 shadow-[0_8px_30px_rgba(29,78,137,0.06)] rounded-2xl"><CardHeader><div className="flex flex-wrap gap-2">{(isLearner ? [["insight", "Preguntar"], ["activity", "Ayuda de estudio"]] : [["activity", "Actividad"], ["communication", "Comunicado"], ["planning", "Planeación"], ["insight", "Análisis"]]).map(([value, label]) => <button key={value} onClick={() => setKind(value as typeof kind)} className={`rounded-xl px-3 py-2 text-xs font-semibold transition ${kind === value ? "bg-[var(--edc-secondary)] text-[var(--edc-primary)]" : "bg-slate-50 text-slate-500 hover:bg-slate-100"}`}>{label}</button>)}</div></CardHeader><CardContent><label className="block text-sm font-medium text-slate-700">¿En qué te ayudo?<Textarea value={prompt} onChange={event => setPrompt(event.target.value)} className="mt-2 min-h-28 text-sm" /></label><Button onClick={submit} disabled={mutation.isPending || !prompt} className="mt-4 rounded-xl bg-[var(--edc-primary)]">{mutation.isPending ? "Pensando..." : "Generar borrador"}<Sparkles className="ml-2 h-4 w-4" /></Button>{result ? <div className="mt-6 rounded-2xl border border-[var(--edc-accent)] bg-[var(--edc-surface)] p-5"><div className="flex items-center justify-between gap-3"><div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.14em] text-[var(--edc-primary)]"><CheckCircle2 className="h-4 w-4" />Borrador para revisión</div><button onClick={() => navigator.clipboard?.writeText(result).then(() => toast.success("Borrador copiado."))} className="text-xs font-medium text-slate-400 hover:text-slate-700">Copiar</button></div><div className="prose prose-sm mt-4 max-w-none whitespace-pre-wrap leading-6 text-slate-600">{result}</div><div className="mt-5 flex items-center gap-2 border-t border-[#dceeff] pt-4 text-xs text-slate-400"><CircleHelp className="h-4 w-4" />Revisa y edita este contenido antes de usarlo.</div></div> : <div className="mt-6 rounded-2xl border border-dashed border-slate-200 bg-slate-50/70 p-6 text-center"><div className="mx-auto flex h-10 w-10 items-center justify-center rounded-xl bg-white text-slate-400 shadow-sm"><BrainCircuit className="h-5 w-5" /></div><p className="mt-3 text-sm font-semibold text-slate-700">Tu espacio de trabajo con IA</p><p className="mt-1 text-xs leading-5 text-slate-400">Prueba una de las sugerencias o escribe una pregunta contextual.</p></div>}</CardContent></Card></div></div>;
}


const identityRoleLabels: Record<string, string> = {
  SUPER_ADMIN: "Super administrador",
  SCHOOL_ADMIN: "Administrador escolar",
  RECTOR: "Rectoría",
  COORDINATOR: "Coordinación",
  TEACHER: "Docente",
  STUDENT: "Estudiante",
  GUARDIAN: "Acudiente",
};

function UsersPage({ role, onPreview }: { role: EduRole; onPreview: (role: EduRole) => void }) {
  const [tab, setTab] = useState<"users" | "invitations" | "relationships" | "roles">("users");
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState("ALL");
  const [statusFilter, setStatusFilter] = useState("ALL");
  const [selectedUserId, setSelectedUserId] = useState<number | null>(null);
  const [showCreate, setShowCreate] = useState(false);
  const [showInvite, setShowInvite] = useState(false);
  const [showRelationship, setShowRelationship] = useState(false);
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [email, setEmail] = useState("");
  const [newRole, setNewRole] = useState("TEACHER");
  const [newStatus, setNewStatus] = useState("ACTIVE");
  const [inviteRole, setInviteRole] = useState("TEACHER");
  const [guardianId, setGuardianId] = useState("");
  const [studentId, setStudentId] = useState("");
  const [relationshipType, setRelationshipType] = useState("PARENT");
  const usersInput = useMemo(() => ({ role, search: search || undefined, roleKey: roleFilter as any, status: statusFilter as any, limit: 50, offset: 0 }), [role, search, roleFilter, statusFilter]);
  const { data: usersData, isLoading: usersLoading, refetch: refetchUsers } = trpc.identity.users.useQuery(usersInput);
  const invitationsQuery = trpc.identity.invitations.useQuery({ role }, { enabled: tab === "invitations" });
  const relationshipsQuery = trpc.identity.relationships.useQuery({ role, guardianUserId: guardianId ? Number(guardianId) : undefined }, { enabled: tab === "relationships" && Boolean(guardianId) });
  const rolesQuery = trpc.identity.roles.useQuery({ role }, { enabled: tab === "roles" });
  const profileInput = useMemo(() => ({ role, userId: selectedUserId ?? 0 }), [role, selectedUserId]);
  const profileQuery = trpc.identity.profile.useQuery(profileInput, { enabled: selectedUserId !== null });
  const refresh = () => { void refetchUsers(); void invitationsQuery.refetch(); void relationshipsQuery.refetch(); };
  const createMutation = trpc.identity.createUser.useMutation({ onSuccess: () => { toast.success("Usuario creado y vinculado a la institución."); setShowCreate(false); setFirstName(""); setLastName(""); setEmail(""); refresh(); }, onError: error => toast.error(error.message) });
  const inviteMutation = trpc.identity.createInvitation.useMutation({ onSuccess: () => { toast.success("Invitación registrada. El correo real aún no está conectado."); setShowInvite(false); setEmail(""); refresh(); }, onError: error => toast.error(error.message) });
  const roleMutation = trpc.identity.changeRole.useMutation({ onSuccess: () => { toast.success("Rol actualizado."); refresh(); void profileQuery.refetch(); }, onError: error => toast.error(error.message) });
  const statusMutation = trpc.identity.setStatus.useMutation({ onSuccess: (_, variables) => { toast.success(variables.status === "ACTIVE" ? "Acceso reactivado." : "Acceso suspendido sin eliminar historial."); refresh(); void profileQuery.refetch(); }, onError: error => toast.error(error.message) });
  const relationshipMutation = trpc.identity.createRelationship.useMutation({ onSuccess: () => { toast.success("Relación acudiente-estudiante creada."); setShowRelationship(false); refresh(); }, onError: error => toast.error(error.message) });
  const rows = usersData?.rows ?? [];
  const guardians = rows.filter((item: any) => item.membershipRole === "GUARDIAN");
  const students = rows.filter((item: any) => item.membershipRole === "STUDENT");
  const inputClass = "mt-2 h-10 rounded-xl border-slate-200 bg-white text-sm";
  const closeOverlays = () => { setShowCreate(false); setShowInvite(false); setShowRelationship(false); };
  return <div className="users-workspace">
    <PageHeader eyebrow="Personas e identidad" title="Usuarios" detail="Gestiona las personas que forman parte de tu institución." action={<div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => setShowInvite(true)} className="rounded-xl bg-white"><Send className="mr-2 h-4 w-4" />Invitar usuario</Button><Button onClick={() => setShowCreate(true)} className="rounded-xl bg-[var(--edc-primary)]"><Plus className="mr-2 h-4 w-4" />Crear usuario</Button></div>} />
    <div className="mb-6 grid gap-3 sm:grid-cols-3"><Card className="surface-card rounded-2xl"><CardContent className="p-4"><p className="text-xs uppercase tracking-[0.14em] text-slate-400">Personas vinculadas</p><p className="mt-2 text-2xl font-semibold text-slate-800">{usersData?.total ?? "—"}</p><p className="mt-1 text-xs text-slate-400">Con acceso segmentado por rol</p></CardContent></Card><Card className="surface-card rounded-2xl"><CardContent className="p-4"><p className="text-xs uppercase tracking-[0.14em] text-slate-400">Activos</p><p className="mt-2 text-2xl font-semibold text-emerald-600">{rows.filter((item: any) => item.status === "ACTIVE").length}</p><p className="mt-1 text-xs text-slate-400">Pueden entrar a EduCore</p></CardContent></Card><Card className="surface-card rounded-2xl"><CardContent className="p-4"><p className="text-xs uppercase tracking-[0.14em] text-slate-400">Invitaciones</p><p className="mt-2 text-2xl font-semibold text-[var(--edc-primary)]">{invitationsQuery.data?.filter((item: any) => item.status === "PENDING").length ?? "—"}</p><p className="mt-1 text-xs text-slate-400">Pendientes de aceptación</p></CardContent></Card></div>
    <div className="mb-6 flex flex-wrap gap-1 rounded-2xl border border-slate-200 bg-white p-1.5 shadow-sm">{([['users', 'Personas'], ['invitations', 'Invitaciones'], ['relationships', 'Acudientes'], ['roles', 'Roles y permisos']] as const).map(([value, label]) => <button key={value} onClick={() => setTab(value)} className={`rounded-xl px-4 py-2.5 text-sm font-medium ${tab === value ? "bg-[var(--edc-secondary)] text-[var(--edc-primary)]" : "text-slate-500 hover:bg-slate-50"}`}>{label}</button>)}</div>
    {tab === "users" ? <>
      <Card className="surface-card rounded-2xl"><CardContent className="p-4"><div className="grid gap-3 lg:grid-cols-[1fr_180px_180px]"><label className="relative block"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><Input value={search} onChange={event => setSearch(event.target.value)} placeholder="Buscar por nombre o correo" className="h-11 rounded-xl pl-9" /></label><select value={roleFilter} onChange={event => setRoleFilter(event.target.value)} className="h-11 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-600"><option value="ALL">Todos los roles</option>{Object.entries(identityRoleLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><select value={statusFilter} onChange={event => setStatusFilter(event.target.value)} className="h-11 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-600"><option value="ALL">Todos los estados</option><option value="ACTIVE">Activos</option><option value="INVITED">Invitados</option><option value="SUSPENDED">Suspendidos</option><option value="INACTIVE">Inactivos</option></select></div></CardContent></Card>
      <Card className="mt-4 surface-card rounded-2xl"><CardHeader><div className="flex items-center justify-between"><div><CardTitle className="text-base">Personas de la institución</CardTitle><p className="mt-1 text-xs text-slate-400">Los permisos se resuelven en el servidor a partir de la membresía activa.</p></div><div className="hidden items-center gap-2 text-xs text-slate-400 sm:flex"><ShieldCheck className="h-4 w-4 text-emerald-500" />Datos protegidos</div></div></CardHeader><CardContent className="p-0">{usersLoading ? <div className="p-6"><div className="h-14 animate-pulse rounded-xl bg-slate-100" /></div> : rows.length === 0 ? <div className="p-6"><EmptyState title="Aún no hay usuarios" detail="Invita a tu equipo para comenzar a utilizar EduCore." icon={Users} /></div> : <div className="divide-y divide-slate-100">{rows.map((item: any) => <div key={item.id} className="flex flex-col gap-4 px-5 py-4 transition hover:bg-slate-50/70 sm:flex-row sm:items-center"><div className="flex min-w-0 flex-1 items-center gap-3"><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-[var(--edc-secondary)] text-sm font-semibold text-[var(--edc-primary)]">{initials(item.name ?? item.email ?? "Usuario")}</div><div className="min-w-0"><p className="truncate text-sm font-semibold text-slate-800">{item.name ?? "Usuario sin nombre"}</p><p className="truncate text-xs text-slate-400">{item.email ?? "Sin correo"}</p></div></div><div className="flex flex-wrap items-center gap-2 sm:w-48"><Badge variant="outline" className="border-slate-200 bg-slate-50 text-xs text-slate-600">{identityRoleLabels[item.membershipRole] ?? item.membershipRole}</Badge><StatusBadge status={item.status} /></div><div className="flex items-center gap-2 sm:w-40 sm:justify-end"><button onClick={() => setSelectedUserId(item.id)} className="rounded-xl px-3 py-2 text-xs font-semibold text-[var(--edc-primary)] hover:bg-[var(--edc-secondary)]">Ver perfil</button>{item.status === "SUSPENDED" ? <button onClick={() => statusMutation.mutate({ role, userId: item.id, status: "ACTIVE" })} className="rounded-xl p-2 text-emerald-600 hover:bg-emerald-50" title="Reactivar acceso"><Check className="h-4 w-4" /></button> : <button onClick={() => statusMutation.mutate({ role, userId: item.id, status: "SUSPENDED" })} className="rounded-xl p-2 text-slate-400 hover:bg-rose-50 hover:text-rose-600" title="Suspender acceso"><ShieldCheck className="h-4 w-4" /></button>}</div></div>)}</div>}</CardContent></Card>
    </> : tab === "invitations" ? <div className="grid gap-5 lg:grid-cols-[1fr_0.7fr]"><Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Invitaciones institucionales</CardTitle><p className="mt-1 text-xs text-slate-400">Los tokens no se muestran después de crear la invitación.</p></CardHeader><CardContent className="space-y-3">{(invitationsQuery.data ?? []).length === 0 ? <EmptyState title="Sin invitaciones" detail="Invita docentes, estudiantes, acudientes o administradores autorizados." icon={Send} /> : (invitationsQuery.data ?? []).map((item: any) => <div key={item.id} className="flex flex-col gap-3 rounded-2xl border border-slate-100 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-semibold text-slate-700">{item.email}</p><p className="mt-1 text-xs text-slate-400">{identityRoleLabels[item.roleKey] ?? item.roleKey} · vence {formatDate(item.expiresAt)}</p></div><StatusBadge status={item.status} /></div>)}</CardContent></Card><Card className="surface-card rounded-2xl bg-[var(--edc-secondary)]"><CardContent className="p-6"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-white text-[var(--edc-primary)]"><Send className="h-5 w-5" /></div><h2 className="mt-5 text-lg font-semibold text-slate-800">Correo preparado para conectar</h2><p className="mt-2 text-sm leading-6 text-slate-500">La infraestructura de invitaciones persiste estado, expiración y auditoría. Este entorno usa un fallback de desarrollo claramente indicado; no se finge el envío real.</p><Button onClick={() => setShowInvite(true)} className="mt-5 rounded-xl bg-[var(--edc-primary)]">Crear invitación</Button></CardContent></Card></div> : tab === "relationships" ? <div className="grid gap-5 lg:grid-cols-[1fr_0.7fr]"><Card className="surface-card rounded-2xl"><CardHeader><label className="mb-4 block text-xs font-semibold uppercase tracking-[0.14em] text-slate-400">Consultar relaciones por acudiente<select value={guardianId} onChange={event => setGuardianId(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm font-medium normal-case tracking-normal text-slate-600"><option value="">Selecciona un acudiente</option>{guardians.map((item: any) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="flex items-center justify-between"><div><CardTitle className="text-base">Acudientes y estudiantes</CardTitle><p className="mt-1 text-xs text-slate-400">Relaciones explícitas, reversibles y aisladas por institución.</p></div><Button onClick={() => setShowRelationship(true)} variant="outline" className="rounded-xl bg-white"><Plus className="mr-2 h-4 w-4" />Vincular</Button></div></CardHeader><CardContent className="space-y-3">{guardians.length === 0 ? <EmptyState title="Sin acudientes" detail="Crea o invita un acudiente para comenzar a vincular estudiantes." icon={Users} /> : guardians.map((guardian: any) => <div key={guardian.id} className="rounded-2xl border border-slate-100 p-4"><div className="flex items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-full bg-violet-50 text-xs font-semibold text-violet-600">{initials(guardian.name)}</div><div><p className="text-sm font-semibold text-slate-700">{guardian.name}</p><p className="text-xs text-slate-400">{guardian.email}</p></div></div><div className="mt-4 rounded-xl bg-slate-50 p-3"><p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-400">Estudiantes asociados</p>{guardianId === String(guardian.id) ? (relationshipsQuery.data ?? []).map((student: any) => <p key={student.id} className="mt-2 text-sm text-slate-600">{student.name}</p>) : null}{guardianId !== String(guardian.id) ? <button onClick={() => setGuardianId(String(guardian.id))} className="mt-2 text-xs font-semibold text-[var(--edc-primary)]">Ver estudiantes vinculados</button> : !(relationshipsQuery.data ?? []).length ? <p className="mt-2 text-xs text-slate-400">Aún no hay estudiantes vinculados.</p> : null}</div></div>)}</CardContent></Card><Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Contexto protegido</CardTitle></CardHeader><CardContent><p className="text-sm leading-6 text-slate-500">Un acudiente solo puede consultar estudiantes vinculados a su membresía en esta institución. Esta relación será la base para reportes, asistencia, calificaciones y EduCore AI.</p><div className="mt-5 rounded-xl bg-emerald-50 p-4 text-xs leading-5 text-emerald-700"><ShieldCheck className="mb-2 h-4 w-4" />Privacidad por mínimo privilegio.</div></CardContent></Card></div> : <div className="grid gap-5 lg:grid-cols-[0.75fr_1.25fr]"><Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Roles disponibles</CardTitle><p className="mt-1 text-xs text-slate-400">La jerarquía orienta; los permisos explícitos autorizan.</p></CardHeader><CardContent className="space-y-2">{(rolesQuery.data?.roles ?? []).map((item: any) => <div key={item.key} className="rounded-xl border border-slate-100 p-3"><div className="flex items-center justify-between gap-3"><p className="text-sm font-semibold text-slate-700">{item.name ?? identityRoleLabels[item.key]}</p><span className="text-[11px] text-slate-400">Nivel {item.hierarchyLevel}</span></div><p className="mt-1 text-xs leading-5 text-slate-400">{item.description}</p></div>)}</CardContent></Card><Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Permisos por módulo</CardTitle><p className="mt-1 text-xs text-slate-400">Catálogo centralizado para futuras configuraciones avanzadas.</p></CardHeader><CardContent className="grid gap-2 sm:grid-cols-2">{(rolesQuery.data?.permissions ?? []).map((permission: any) => <div key={permission.key} className="rounded-xl bg-slate-50 p-3"><p className="text-xs font-semibold text-slate-700">{permission.name}</p><p className="mt-1 text-[11px] leading-4 text-slate-400">{permission.description}</p></div>)}</CardContent></Card></div>}
    {selectedUserId !== null && <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/20 p-4 backdrop-blur-sm" onClick={() => setSelectedUserId(null)}><Card className="max-h-[90vh] w-full max-w-2xl overflow-auto rounded-2xl border-0 shadow-2xl" onClick={event => event.stopPropagation()}><CardHeader className="flex flex-row items-start justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-[var(--edc-accent)]">Perfil institucional</p><CardTitle className="mt-2">{profileQuery.data?.name ?? "Cargando perfil..."}</CardTitle><p className="mt-1 text-sm text-slate-400">{profileQuery.data?.email}</p></div><button onClick={() => setSelectedUserId(null)} className="rounded-lg p-2 text-slate-400 hover:bg-slate-100"><X className="h-4 w-4" /></button></CardHeader><CardContent className="space-y-5">{profileQuery.data ? <><div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-400">Rol</p><p className="mt-1 text-sm font-semibold text-slate-700">{identityRoleLabels[profileQuery.data.membership?.roleKey] ?? profileQuery.data.membership?.roleKey}</p></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-400">Estado</p><div className="mt-1"><StatusBadge status={profileQuery.data.status} /></div></div><div className="rounded-xl bg-slate-50 p-3"><p className="text-[11px] text-slate-400">Institución</p><p className="mt-1 truncate text-sm font-semibold text-slate-700">{profileQuery.data.school?.name}</p></div></div><div className="grid gap-3 sm:grid-cols-2"><label className="block text-sm font-medium text-slate-700">Cambiar rol<select value={profileQuery.data.membership?.roleKey} onChange={event => { const nextRole = event.target.value as any; if (window.confirm(`¿Cambiar el rol de este usuario a ${identityRoleLabels[nextRole]}?`)) roleMutation.mutate({ role, userId: (profileQuery.data?.id ?? selectedUserId ?? 0), roleKey: nextRole }); }} className={inputClass}>{Object.entries(identityRoleLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><div><p className="text-sm font-medium text-slate-700">Acceso</p>{profileQuery.data.status === "SUSPENDED" ? <Button onClick={() => { if (window.confirm("¿Reactivar el acceso de este usuario?")) statusMutation.mutate({ role, userId: (profileQuery.data?.id ?? selectedUserId ?? 0), status: "ACTIVE" }); }} className="mt-2 rounded-xl bg-emerald-600">Reactivar acceso</Button> : <Button variant="outline" onClick={() => { if (window.confirm("¿Suspender el acceso? El historial académico se conservará.")) statusMutation.mutate({ role, userId: (profileQuery.data?.id ?? selectedUserId ?? 0), status: "SUSPENDED" }); }} className="mt-2 rounded-xl bg-white text-rose-600">Suspender acceso</Button>}</div></div>{profileQuery.data.teacherProfile ? <div className="rounded-2xl bg-blue-50/70 p-4"><p className="text-sm font-semibold text-slate-700">Perfil docente</p><p className="mt-2 text-xs text-slate-500">Código {profileQuery.data.teacherProfile.employeeCode} · {profileQuery.data.teacherProfile.specialties}</p></div> : null}{profileQuery.data.studentProfile ? <div className="rounded-2xl bg-emerald-50/70 p-4"><p className="text-sm font-semibold text-slate-700">Perfil estudiantil</p><p className="mt-2 text-xs text-slate-500">Código {profileQuery.data.studentProfile.studentCode} · {profileQuery.data.studentProfile.course}</p></div> : null}{profileQuery.data.guardianProfile ? <div className="rounded-2xl bg-violet-50/70 p-4"><p className="text-sm font-semibold text-slate-700">Estudiantes vinculados</p><p className="mt-2 text-xs text-slate-500">{profileQuery.data.linkedStudents?.length ? profileQuery.data.linkedStudents.map((student: any) => student.name).join(" · ") : "Aún no hay relaciones registradas."}</p></div> : null}<div><p className="text-xs font-semibold uppercase tracking-[0.14em] text-slate-400">Vista previa controlada</p><div className="mt-2 flex flex-wrap gap-2">{([['teacher', 'Docente'], ['student', 'Estudiante'], ['guardian', 'Acudiente']] as const).map(([previewRole, label]) => <button key={previewRole} onClick={() => { setSelectedUserId(null); onPreview(previewRole); }} className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-50">Ver como {label}</button>)}</div><p className="mt-2 text-[11px] leading-4 text-slate-400">La vista demo cambia el contexto de lectura; las mutaciones siguen protegidas por RBAC server-side.</p></div></> : <div className="py-10 text-center text-sm text-slate-400">Cargando información...</div>}</CardContent></Card></div>}
    {(showCreate || showInvite || showRelationship) && <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/20 p-4 backdrop-blur-sm" onClick={closeOverlays}><Card className="w-full max-w-lg rounded-2xl border-0 shadow-2xl" onClick={event => event.stopPropagation()}><CardHeader className="flex flex-row items-start justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.16em] text-[var(--edc-accent)]">{showCreate ? "Nueva identidad" : showInvite ? "Acceso institucional" : "Relación protegida"}</p><CardTitle className="mt-2">{showCreate ? "Crear usuario" : showInvite ? "Invitar usuario" : "Vincular acudiente"}</CardTitle></div><button onClick={closeOverlays} className="rounded-lg p-2 text-slate-400 hover:bg-slate-100"><X className="h-4 w-4" /></button></CardHeader><CardContent className="space-y-4">{showRelationship ? <><label className="block text-sm font-medium text-slate-700">Acudiente<select value={guardianId} onChange={event => setGuardianId(event.target.value)} className={inputClass}><option value="">Selecciona una persona</option>{guardians.map((item: any) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="block text-sm font-medium text-slate-700">Estudiante<select value={studentId} onChange={event => setStudentId(event.target.value)} className={inputClass}><option value="">Selecciona una persona</option>{students.map((item: any) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="block text-sm font-medium text-slate-700">Relación<select value={relationshipType} onChange={event => setRelationshipType(event.target.value)} className={inputClass}><option value="PARENT">Padre / madre</option><option value="LEGAL_GUARDIAN">Tutor legal</option><option value="OTHER">Otra relación</option></select></label><Button disabled={!guardianId || !studentId || relationshipMutation.isPending} onClick={() => relationshipMutation.mutate({ role, guardianUserId: Number(guardianId), studentUserId: Number(studentId), relationshipType: relationshipType as any, isPrimary: true })} className="w-full rounded-xl bg-[var(--edc-primary)]">Crear relación</Button></> : <><div className="grid gap-4 sm:grid-cols-2"><label className="block text-sm font-medium text-slate-700">Nombre<Input value={firstName} onChange={event => setFirstName(event.target.value)} className={inputClass} /></label><label className="block text-sm font-medium text-slate-700">Apellido<Input value={lastName} onChange={event => setLastName(event.target.value)} className={inputClass} /></label></div><label className="block text-sm font-medium text-slate-700">Correo institucional<Input type="email" value={email} onChange={event => setEmail(event.target.value)} placeholder="persona@colegio.edu.co" className={inputClass} /></label><label className="block text-sm font-medium text-slate-700">Tipo de usuario<select value={showCreate ? newRole : inviteRole} onChange={event => showCreate ? setNewRole(event.target.value) : setInviteRole(event.target.value)} className={inputClass}>{Object.entries(identityRoleLabels).filter(([key]) => key !== "SUPER_ADMIN").map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>{showCreate ? <label className="block text-sm font-medium text-slate-700">Estado inicial<select value={newStatus} onChange={event => setNewStatus(event.target.value)} className={inputClass}><option value="ACTIVE">Activo</option><option value="INVITED">Invitado</option><option value="SUSPENDED">Suspendido</option></select></label> : <p className="rounded-xl bg-amber-50 p-3 text-xs leading-5 text-amber-700">Se creará una invitación pendiente. En este entorno no se envía correo real y el token no se muestra.</p>}<Button disabled={!firstName || !lastName || !email || createMutation.isPending || inviteMutation.isPending} onClick={() => showCreate ? createMutation.mutate({ role, firstName, lastName, email, roleKey: newRole as any, status: newStatus as any }) : inviteMutation.mutate({ role, email, roleKey: inviteRole as any })} className="w-full rounded-xl bg-[var(--edc-primary)]">{showCreate ? "Crear y vincular usuario" : "Registrar invitación"}</Button></>}</CardContent></Card></div>}
  </div>;
}

function SettingsPage({ data, role, onChanged }: { data: any; role: EduRole; onChanged: () => void }) {
  const canEdit = role === "admin";
  const [tab, setTab] = useState<"institution" | "appearance" | "periods">("institution");
  const school = data.school;
  const [name, setName] = useState(school.name); const [shortName, setShortName] = useState(school.shortName ?? "Gimnasio Moderno");
  const [city, setCity] = useState(school.city); const [department, setDepartment] = useState(school.department ?? "Valle del Cauca"); const [country, setCountry] = useState(school.country ?? "Colombia");
  const [description, setDescription] = useState(school.description ?? "Plataforma institucional para centralizar la vida académica."); const [website, setWebsite] = useState(school.website ?? "https://educore.co");
  const [email, setEmail] = useState(school.email ?? "contacto@educore.co"); const [phone, setPhone] = useState(school.phone ?? "+57 602 555 0101"); const [address, setAddress] = useState(school.address ?? "Cali, Valle del Cauca");
  const [academicYear, setAcademicYear] = useState(school.academicYear); const [primaryColor, setPrimaryColor] = useState(school.primaryColor); const [secondaryColor, setSecondaryColor] = useState(school.secondaryColor);
  const [accentColor, setAccentColor] = useState(school.accentColor ?? "#8ec6fa"); const [backgroundColor, setBackgroundColor] = useState(school.backgroundColor ?? "#f7f9fc"); const [surfaceColor, setSurfaceColor] = useState(school.surfaceColor ?? "#ffffff");
  const [textColor, setTextColor] = useState(school.textColor ?? "#182131"); const [mutedTextColor, setMutedTextColor] = useState(school.mutedTextColor ?? "#7a8798"); const [themeMode, setThemeMode] = useState(school.themeMode ?? "light"); const [borderRadius, setBorderRadius] = useState(school.borderRadius ?? "12px");
  const [logoUrl, setLogoUrl] = useState<string | null>(school.logoUrl ?? null); const [suggestedPalette, setSuggestedPalette] = useState<{ primary: string; secondary: string; accent: string } | null>(null);
  const [periodName, setPeriodName] = useState(""); const [periodStart, setPeriodStart] = useState(""); const [periodEnd, setPeriodEnd] = useState("");
  const schoolMutation = trpc.educore.updateSchool.useMutation({ onSuccess: () => { toast.success("Información institucional guardada correctamente."); onChanged(); } });
  const uploadMutation = trpc.educore.uploadSchoolLogo.useMutation({ onSuccess: result => { setLogoUrl(result.logoUrl ?? null); toast.success("Escudo actualizado correctamente."); onChanged(); }, onError: error => toast.error(`No se pudo subir el escudo: ${error.message}`) });
  const periodMutation = trpc.educore.createAcademicPeriod.useMutation({ onSuccess: () => { toast.success("Periodo creado correctamente."); setPeriodName(""); setPeriodStart(""); setPeriodEnd(""); onChanged(); } });
  const save = () => schoolMutation.mutate({ role, name, shortName, city, department, country, description, website, email, phone, address, academicYear, primaryColor, secondaryColor, accentColor, backgroundColor, surfaceColor, textColor, mutedTextColor, themeMode: themeMode as "light" | "dark", borderRadius, logoUrl });
  const readLogo = (file: File) => { const reader = new FileReader(); reader.onload = () => { const result = String(reader.result); setLogoUrl(result); const image = new Image(); image.onload = () => { const canvas = document.createElement("canvas"); canvas.width = 1; canvas.height = 1; const ctx = canvas.getContext("2d"); if (ctx) { ctx.drawImage(image, 0, 0, 1, 1); const pixel = ctx.getImageData(0, 0, 1, 1).data; const hex = `#${[pixel[0], pixel[1], pixel[2]].map(value => value.toString(16).padStart(2, "0")).join("")}`; setSuggestedPalette({ primary: hex, secondary: "#eaf4ff", accent: "#8ec6fa" }); } }; image.src = result; if (canEdit) uploadMutation.mutate({ role, fileName: file.name, contentType: file.type as "image/png" | "image/jpeg" | "image/svg+xml", dataBase64: result }); }; reader.readAsDataURL(file); };
  const inputClass = "mt-2 h-10 rounded-xl border-slate-200 bg-white text-sm";
  return <div className="settings-workspace"><PageHeader eyebrow="Administración" title="Configuración institucional" detail="La identidad y el calendario académico de tu colegio, en un solo lugar." action={canEdit && tab !== "periods" ? <Button onClick={save} disabled={schoolMutation.isPending} className="rounded-xl bg-[var(--edc-primary)] shadow-[0_5px_14px_rgba(36,117,207,0.16)]"><Check className="mr-2 h-4 w-4" />{schoolMutation.isPending ? "Guardando..." : "Guardar cambios"}</Button> : null} /><div className="mb-6 flex flex-wrap gap-1 rounded-2xl border border-slate-200 bg-white p-1.5 shadow-sm">{([["institution", "Institución"], ["appearance", "Apariencia"], ["periods", "Año y periodos"]] as const).map(([value, label]) => <button key={value} onClick={() => setTab(value)} className={`rounded-xl px-4 py-2.5 text-sm font-medium ${tab === value ? "bg-[var(--edc-secondary)] text-[var(--edc-primary)]" : "text-slate-500 hover:bg-slate-50"}`}>{label}</button>)}</div>{tab === "institution" ? <div className="grid gap-5 xl:grid-cols-[1fr_0.65fr]"><Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Identidad institucional</CardTitle><p className="mt-1 text-xs text-slate-400">Información visible para la comunidad educativa.</p></CardHeader><CardContent className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><label className="block text-sm font-medium text-slate-700">Nombre institucional<Input value={name} onChange={event => setName(event.target.value)} className={inputClass} /></label><label className="block text-sm font-medium text-slate-700">Nombre corto<Input value={shortName} onChange={event => setShortName(event.target.value)} className={inputClass} /></label></div><label className="block text-sm font-medium text-slate-700">Descripción<Textarea value={description} onChange={event => setDescription(event.target.value)} className="mt-2 min-h-24" /></label><div className="grid gap-4 sm:grid-cols-3"><label className="block text-sm font-medium text-slate-700">Ciudad<Input value={city} onChange={event => setCity(event.target.value)} className={inputClass} /></label><label className="block text-sm font-medium text-slate-700">Departamento<Input value={department} onChange={event => setDepartment(event.target.value)} className={inputClass} /></label><label className="block text-sm font-medium text-slate-700">País<Input value={country} onChange={event => setCountry(event.target.value)} className={inputClass} /></label></div><div className="grid gap-4 sm:grid-cols-2"><label className="block text-sm font-medium text-slate-700">Sitio web<Input value={website} onChange={event => setWebsite(event.target.value)} className={inputClass} /></label><label className="block text-sm font-medium text-slate-700">Correo institucional<Input value={email} onChange={event => setEmail(event.target.value)} className={inputClass} /></label><label className="block text-sm font-medium text-slate-700">Teléfono<Input value={phone} onChange={event => setPhone(event.target.value)} className={inputClass} /></label><label className="block text-sm font-medium text-slate-700">Dirección<Input value={address} onChange={event => setAddress(event.target.value)} className={inputClass} /></label></div></CardContent></Card><Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Escudo institucional</CardTitle><p className="mt-1 text-xs text-slate-400">PNG, JPG o SVG · máximo 2.5 MB.</p></CardHeader><CardContent><div className="flex min-h-44 items-center justify-center rounded-2xl border border-dashed border-slate-200 bg-slate-50/80 p-5">{logoUrl ? <img src={logoUrl} alt="Escudo institucional" className="max-h-32 max-w-[80%] object-contain" /> : <div className="flex h-20 w-20 items-center justify-center rounded-2xl bg-[var(--edc-secondary)] text-3xl font-semibold text-[var(--edc-primary)]">E</div>}</div>{canEdit ? <label className="mt-4 flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium text-slate-600 hover:bg-slate-50"><Upload className="h-4 w-4" />Cambiar escudo<input type="file" accept="image/png,image/jpeg,image/svg+xml" className="hidden" onChange={event => { const file = event.target.files?.[0]; if (file) readLogo(file); }} /></label> : null}{suggestedPalette ? <div className="mt-4 rounded-xl border border-[var(--edc-accent)] bg-[var(--edc-surface)] p-4"><p className="text-sm font-semibold text-slate-700">Paleta sugerida</p><div className="mt-3 flex gap-2">{[suggestedPalette.primary, suggestedPalette.secondary, suggestedPalette.accent].map(color => <span key={color} className="h-8 flex-1 rounded-lg border border-white shadow-sm" style={{ backgroundColor: color }} title={color} />)}</div><div className="mt-3 flex gap-2"><button onClick={() => { setPrimaryColor(suggestedPalette.primary); setSecondaryColor(suggestedPalette.secondary); setAccentColor(suggestedPalette.accent); setSuggestedPalette(null); }} className="rounded-lg bg-[var(--edc-primary)] px-3 py-2 text-xs font-semibold text-white">Aplicar</button><button onClick={() => setSuggestedPalette(null)} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-semibold text-slate-500">Cancelar</button></div></div> : null}</CardContent></Card></div> : tab === "appearance" ? <div className="grid gap-5 xl:grid-cols-[0.8fr_1.2fr]"><Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Identidad visual</CardTitle><p className="mt-1 text-xs text-slate-400">Cambia colores en vivo; guarda cuando estés conforme.</p></CardHeader><CardContent className="space-y-4">{([["Color principal", primaryColor, setPrimaryColor], ["Color secundario", secondaryColor, setSecondaryColor], ["Color de acento", accentColor, setAccentColor], ["Fondo", backgroundColor, setBackgroundColor], ["Superficie", surfaceColor, setSurfaceColor], ["Texto", textColor, setTextColor], ["Texto secundario", mutedTextColor, setMutedTextColor]] as const).map(([label, value, setter]) => <label key={label} className="flex items-center justify-between gap-3 text-sm font-medium text-slate-700"><span>{label}</span><span className="flex items-center gap-2"><input type="color" value={value} onChange={event => setter(event.target.value)} className="h-9 w-11 cursor-pointer rounded-lg border-0 bg-transparent" /><Input value={value} onChange={event => setter(event.target.value)} className="h-9 w-28 rounded-lg text-xs uppercase" /></span></label>)}<div className="flex items-center justify-between gap-3 border-t border-slate-100 pt-4 text-sm font-medium text-slate-700"><span>Radio de bordes</span><select value={borderRadius} onChange={event => setBorderRadius(event.target.value)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-xs"><option value="8px">Compacto</option><option value="12px">Suave</option><option value="16px">Amplio</option></select></div><div className="flex items-center justify-between gap-3 text-sm font-medium text-slate-700"><span>Tema</span><select value={themeMode} onChange={event => setThemeMode(event.target.value)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-xs"><option value="light">Claro</option><option value="dark">Oscuro</option></select></div></CardContent></Card><Card className="surface-card rounded-2xl" style={{ backgroundColor }}><CardHeader><CardTitle className="text-base" style={{ color: textColor }}>Vista previa en vivo</CardTitle><p className="mt-1 text-xs" style={{ color: mutedTextColor }}>Navbar, sidebar, botón, card, tabla y estado.</p></CardHeader><CardContent><div className="overflow-hidden rounded-2xl border bg-white" style={{ borderColor: secondaryColor }}><div className="flex items-center justify-between border-b px-4 py-3" style={{ borderColor: secondaryColor, backgroundColor: surfaceColor }}><div className="flex items-center gap-2"><div className="flex h-7 w-7 items-center justify-center rounded-lg" style={{ backgroundColor: secondaryColor, color: primaryColor }}>E</div><span className="text-sm font-semibold" style={{ color: textColor }}>{shortName}</span></div><span className="text-xs" style={{ color: mutedTextColor }}>EduCore</span></div><div className="grid grid-cols-[120px_1fr]"><div className="space-y-2 border-r p-3" style={{ borderColor: secondaryColor }}><div className="rounded-lg px-2 py-2 text-xs font-semibold" style={{ backgroundColor: secondaryColor, color: primaryColor }}>Inicio</div><div className="px-2 py-2 text-xs" style={{ color: mutedTextColor }}>Académico</div><div className="px-2 py-2 text-xs" style={{ color: mutedTextColor }}>Reportes</div></div><div className="space-y-4 p-4"><div><p className="text-xs" style={{ color: mutedTextColor }}>Vista institucional</p><p className="mt-1 text-lg font-semibold" style={{ color: textColor }}>Todo bajo control.</p></div><div className="rounded-xl border p-4" style={{ borderColor: secondaryColor, backgroundColor: surfaceColor }}><p className="text-xs" style={{ color: mutedTextColor }}>Promedio institucional</p><p className="mt-2 text-2xl font-semibold" style={{ color: textColor }}>4.1</p><span className="mt-2 inline-flex rounded-full px-2 py-1 text-[10px] font-semibold" style={{ backgroundColor: accentColor, color: textColor }}>Listo</span></div><button className="rounded-xl px-3 py-2 text-xs font-semibold text-white" style={{ backgroundColor: primaryColor }}>Guardar cambios</button></div></div></div></CardContent></Card></div> : <div className="grid gap-5 xl:grid-cols-[1fr_0.75fr]"><Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Año académico y periodos</CardTitle><p className="mt-1 text-xs text-slate-400">Esta estructura quedará disponible para la lógica académica avanzada.</p></CardHeader><CardContent><label className="block text-sm font-medium text-slate-700">Año académico<Input value={academicYear} onChange={event => setAcademicYear(event.target.value)} className={inputClass} /></label><div className="mt-6 space-y-3">{data.academicPeriods?.map((period: any) => <div key={period.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-100 bg-slate-50/60 p-3"><div><p className="text-sm font-semibold text-slate-700">{period.name}</p><p className="mt-1 text-xs text-slate-400">{formatDate(period.startDate)} — {formatDate(period.endDate)}</p></div><StatusBadge status={period.status} /></div>)}</div></CardContent></Card><Card className="surface-card rounded-2xl"><CardHeader><CardTitle className="text-base">Crear periodo</CardTitle></CardHeader><CardContent className="space-y-4"><Input value={periodName} onChange={event => setPeriodName(event.target.value)} placeholder="Ej. Periodo 5" /><label className="block text-sm font-medium text-slate-700">Inicio<Input type="date" value={periodStart} onChange={event => setPeriodStart(event.target.value)} className={inputClass} /></label><label className="block text-sm font-medium text-slate-700">Fin<Input type="date" value={periodEnd} onChange={event => setPeriodEnd(event.target.value)} className={inputClass} /></label><Button disabled={!canEdit || !periodName || !periodStart || !periodEnd || periodMutation.isPending} onClick={() => periodMutation.mutate({ role, name: periodName, startDate: new Date(periodStart), endDate: new Date(periodEnd), status: "Programado" })} className="w-full rounded-xl bg-[var(--edc-primary)]">Crear periodo</Button></CardContent></Card></div>}</div>;
}

function LoginScreen({ onDemo, school }: { onDemo: (role: EduRole) => void; school?: any }) {
  return <div className="flex min-h-screen items-center justify-center page-shell px-4 py-10" style={{ "--edc-primary": school?.primaryColor ?? "#2475cf", "--edc-secondary": school?.secondaryColor ?? "#eaf4ff", "--edc-background": school?.backgroundColor ?? "#f7f9fc", "--edc-surface": school?.surfaceColor ?? "#ffffff" } as React.CSSProperties}><div className="w-full max-w-5xl"><div className="login-spatial-grid grid overflow-hidden rounded-[28px] border border-slate-200/90 bg-white premium-panel md:grid-cols-[0.85fr_1.15fr]"><div className="bg-[var(--edc-primary)] p-8 text-white sm:p-12"><div className="flex h-11 w-11 items-center justify-center rounded-xl bg-white/15 text-lg font-bold">{school?.logoUrl ? <img src={storageUrl(school.logoUrl)} alt="Escudo institucional" className="h-full w-full rounded-xl object-contain p-1" /> : "E"}</div><p className="mt-14 text-xs font-semibold uppercase tracking-[0.18em] text-blue-100">EduCore · School OS</p><h1 className="mt-4 text-3xl font-semibold leading-tight tracking-[-0.03em] sm:text-4xl">Menos administración.<br />Más educación.</h1><p className="mt-5 max-w-xs text-sm leading-6 text-blue-100">La plataforma inteligente para centralizar la vida académica de tu colegio.</p><div className="mt-12 flex items-center gap-2 text-xs text-blue-100"><ShieldCheck className="h-4 w-4" />Construido para instituciones educativas</div></div><div className="p-8 sm:p-12"><p className="text-xs font-semibold uppercase tracking-[0.16em] text-[var(--edc-accent)]">{school?.name ?? "Gimnasio Moderno del Valle"}</p><h2 className="mt-3 text-2xl font-semibold tracking-tight text-slate-900">Bienvenido a EduCore</h2><p className="mt-2 text-sm leading-6 text-slate-500">Inicia sesión con tu cuenta institucional o explora una vista demo.</p><Button onClick={() => startLogin()} className="mt-7 w-full rounded-xl bg-[var(--edc-primary)] shadow-[0_5px_14px_rgba(36,117,207,0.16)]">Iniciar sesión institucional</Button><div className="my-7 flex items-center gap-3"><div className="h-px flex-1 bg-slate-100" /><span className="text-[10px] uppercase tracking-wider text-slate-400">Explorar demo</span><div className="h-px flex-1 bg-slate-100" /></div><div className="grid grid-cols-2 gap-2">{(["admin", "teacher", "student", "guardian"] as EduRole[]).map(option => <button key={option} onClick={() => onDemo(option)} className="rounded-xl border border-slate-200 px-3 py-3 text-left transition hover:border-[#9ecdf5] hover:bg-[#f7fbff]"><p className="text-xs font-semibold text-slate-700">{roleLabels[option]}</p><p className="mt-1 text-[10px] text-slate-400">Cuenta demo</p></button>)}</div><p className="mt-6 text-center text-[11px] leading-5 text-slate-400">La demo utiliza datos ficticios. No incluye información real de menores.</p></div></div></div></div>;
}

export default function Home() {
  const { user, loading, isAuthenticated, logout } = useAuth();
  const [demoMode, setDemoMode] = useState(false);
  const [role, setRole] = useState<EduRole>(() => (localStorage.getItem("educore-demo-role") as EduRole) || "admin");
  const [selectedStudentId, setSelectedStudentId] = useState<number | undefined>();
  const [section, setSection] = useState<Section>("overview");
  const effectiveRole = role;
  const snapshotInput = useMemo(() => ({ role: effectiveRole, selectedStudentId: effectiveRole === "guardian" ? selectedStudentId : undefined }), [effectiveRole, selectedStudentId]);
  const { data, isLoading, refetch } = trpc.educore.snapshot.useQuery(snapshotInput, { enabled: !loading });
  useEffect(() => { if (data?.school?.name) document.title = `EduCore — ${data.school.name}`; }, [data?.school?.name]);
  const schoolName = data?.school?.name ?? "Gimnasio Moderno del Valle";
  const handleRoleChange = (nextRole: EduRole) => { setRole(nextRole); setSelectedStudentId(undefined); localStorage.setItem("educore-demo-role", nextRole); setSection("overview"); toast.success(`Vista cambiada a ${roleLabels[nextRole]}`); };
  const refresh = () => { void refetch(); };
  if (loading || isLoading) return <div className="flex min-h-screen items-center justify-center bg-[var(--edc-background)]"><div className="flex items-center gap-3 text-sm text-slate-500"><div className="h-5 w-5 animate-spin rounded-full border-2 border-[var(--edc-accent)] border-t-[#368de8]" />Preparando tu espacio EduCore...</div></div>;
  if (!isAuthenticated && !demoMode) return <LoginScreen school={data?.school} onDemo={selectedRole => { handleRoleChange(selectedRole); setDemoMode(true); }} />;
  if (!data) return <div className="flex min-h-screen items-center justify-center bg-[var(--edc-background)] p-6"><EmptyState title="No pudimos cargar tu espacio" detail="Revisa la conexión e inténtalo de nuevo." /></div>;
  const content = section === "overview" ? effectiveRole === "admin" ? <AdminDashboard data={data} setSection={setSection} /> : effectiveRole === "teacher" ? <TeacherDashboard data={data} setSection={setSection} /> : <StudentDashboard data={data} role={effectiveRole} setSection={setSection} selectedStudentId={selectedStudentId} onSelectStudent={setSelectedStudentId} /> : section === "academic" ? <AcademicPage data={data} role={effectiveRole} setSection={setSection} onGradeSaved={refresh} /> : section === "grades" ? <GradeCenterPage role={effectiveRole} school={data.school} /> : section === "classroom" ? <ClassroomPage data={data} role={effectiveRole} onChanged={refresh} setSection={setSection} /> : section === "attendance" ? <AttendancePage data={data} role={effectiveRole} onChanged={refresh} /> : section === "calendar" ? <CalendarPage data={data} /> : section === "communications" ? <CommunicationsPage data={data} role={effectiveRole} onChanged={refresh} /> : section === "reports" ? <ReportsPage data={data} role={effectiveRole} setSection={setSection} /> : section === "ai" ? <AiPage data={data} role={effectiveRole} /> : section === "users" ? <UsersPage role={effectiveRole} onPreview={handleRoleChange} /> : <SettingsPage data={data} role={effectiveRole} onChanged={refresh} />;
  return <AppShell role={effectiveRole} section={section} setSection={setSection} schoolName={schoolName} school={data.school} onRoleChange={handleRoleChange} onLogout={async () => { if (isAuthenticated) await logout(); setDemoMode(false); }} notificationCount={data.notifications.filter((item: any) => !item.read).length}>{content}</AppShell>;
}
